 FOR EACH ROW EXECUTE FUNCTION photo.bump_v2_revision();

-- Source: 00197_session_mutations.sql
-- Server validates SessionPolicy/CapturePolicy JSON Schema and qualified
-- Calibration bytes before calling these DB-only commands. SQL repeats
-- authoritative principal, project, artifact and model-qualification checks.
-- +goose StatementBegin
CREATE FUNCTION photo.ensure_v22_photographer_grant(p_tenant uuid,p_project uuid,
 p_actor uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE grant_id uuid;
BEGIN
 INSERT INTO photo.consent_grants(tenant_id,project_id,purpose,person_id,status,
  epoch,policy_version,actor_id)
 VALUES(p_tenant,p_project,'learning_photographer',NULL,'revoked',1,'v2.2',p_actor)
 ON CONFLICT DO NOTHING;
 SELECT id INTO grant_id FROM photo.consent_grants WHERE tenant_id=p_tenant
  AND project_id=p_project AND purpose='learning_photographer' AND person_id IS NULL;
 IF grant_id IS NULL THEN
  RAISE EXCEPTION 'V22_PROJECT_CONSENT_BOOTSTRAP_FAILED' USING ERRCODE='23514';
 END IF;
 RETURN grant_id;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.ensure_v22_photographer_grant(uuid,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.ensure_v22_photographer_grant(uuid,uuid,uuid) FROM PUBLIC;

-- +goose StatementBegin
CREATE FUNCTION photo.v22_session_policy_ready(p_tenant uuid,p_project uuid,
 p_policy jsonb,p_model_lock_sha text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE calibration_id uuid; calibration_sha text; offset_item jsonb;
 offset_hashes text[]:=ARRAY[]::text[];
BEGIN
 IF jsonb_typeof(p_policy) IS DISTINCT FROM 'object' OR
  (p_policy-'schema_version'-'time_gap_seconds'-'neighbor_count'-'protect_manual_picks'-'camera_offsets'-'calibration')<>'{}'::jsonb OR
  NOT (p_policy ?& ARRAY['schema_version','time_gap_seconds','neighbor_count',
   'protect_manual_picks','camera_offsets','calibration']) OR
  p_policy->>'schema_version' IS DISTINCT FROM '1' OR
  p_policy->>'protect_manual_picks' IS DISTINCT FROM 'true' OR
  jsonb_typeof(p_policy->'schema_version') IS DISTINCT FROM 'number' OR
  jsonb_typeof(p_policy->'time_gap_seconds') IS DISTINCT FROM 'number' OR
  jsonb_typeof(p_policy->'neighbor_count') IS DISTINCT FROM 'number' OR
  jsonb_typeof(p_policy->'protect_manual_picks') IS DISTINCT FROM 'boolean' OR
  jsonb_typeof(p_policy->'calibration') IS DISTINCT FROM 'object' OR
  jsonb_typeof(p_policy->'camera_offsets') IS DISTINCT FROM 'array' OR
  ((p_policy->'calibration')-'artifact_id'-'sha256')<>'{}'::jsonb OR
  NOT ((p_policy->'calibration') ?& ARRAY['artifact_id','sha256']) OR
  coalesce(p_policy->'calibration'->>'artifact_id','') !~
   '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR
  coalesce(p_policy->'calibration'->>'sha256','') !~ '^[0-9a-f]{64}$' OR
  coalesce(p_model_lock_sha,'') !~ '^[0-9a-f]{64}$' OR
  octet_length(p_policy::text)>1048576 THEN RETURN false; END IF;
 IF coalesce(p_policy->>'time_gap_seconds','') !~ '^[0-9]{1,4}$' OR
  coalesce(p_policy->>'neighbor_count','') !~ '^[0-9]{1,2}$' THEN RETURN false; END IF;
 IF (p_policy->>'time_gap_seconds')::int NOT BETWEEN 30 AND 7200 OR
  (p_policy->>'neighbor_count')::int NOT BETWEEN 1 AND 64 OR
  jsonb_array_length(p_policy->'camera_offsets')>32 THEN RETURN false; END IF;
 FOR offset_item IN SELECT value FROM jsonb_array_elements(p_policy->'camera_offsets') LOOP
  IF jsonb_typeof(offset_item) IS DISTINCT FROM 'object' OR
   (offset_item-'camera_hash'-'seconds')<>'{}'::jsonb OR
   NOT (offset_item ?& ARRAY['camera_hash','seconds']) OR
   jsonb_typeof(offset_item->'seconds') IS DISTINCT FROM 'number' OR
   coalesce(offset_item->>'camera_hash','') !~ '^[0-9a-f]{64}$' OR
   coalesce(offset_item->>'seconds','') !~ '^(-|)[0-9]{1,5}$' THEN RETURN false; END IF;
  IF (offset_item->>'seconds')::int NOT BETWEEN -86400 AND 86400 THEN RETURN false; END IF;
  IF offset_item->>'camera_hash'=ANY(offset_hashes) THEN RETURN false; END IF;
  offset_hashes:=array_append(offset_hashes,offset_item->>'camera_hash');
 END LOOP;
 calibration_id:=(p_policy->'calibration'->>'artifact_id')::uuid;
 calibration_sha:=p_policy->'calibration'->>'sha256';
 RETURN EXISTS(SELECT 1 FROM photo.artifacts a WHERE a.tenant_id=p_tenant
  AND a.id=calibration_id AND a.sha256=calibration_sha AND a.state='ready'
  AND a.media_type='application/json' AND a.verified_at IS NOT NULL)
 AND EXISTS(SELECT 1 FROM photo.model_qualifications q WHERE q.tenant_id=p_tenant
  AND q.project_id=p_project AND q.operation='session.describe'
  AND q.operation_version='1' AND q.model_lock_sha=p_model_lock_sha AND q.status='passed');
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_session_policy_ready(uuid,uuid,jsonb,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_session_policy_ready(uuid,uuid,jsonb,text) FROM PUBLIC;

-- +goose StatementBegin
CREATE FUNCTION photo.create_v22_session(p_tenant uuid,p_project uuid,p_collection uuid,
 p_name text,p_policy jsonb,p_capture_policy jsonb,p_model_lock_sha text,
 p_actor uuid,p_session uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE created photo.shoot_sessions%ROWTYPE;
BEGIN
 IF p_tenant IS NULL OR p_project IS NULL OR p_collection IS NULL OR p_actor IS NULL
  OR p_session IS NULL OR length(coalesce(p_name,'')) NOT BETWEEN 1 AND 200 OR
  (p_capture_policy IS NOT NULL AND (jsonb_typeof(p_capture_policy)<>'object'
   OR octet_length(p_capture_policy::text)>1048576)) THEN
  RAISE EXCEPTION 'V22_SESSION_INVALID' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND OR NOT photo.v2_editor_authorized(p_tenant,p_project,p_actor,p_session) THEN
  RAISE EXCEPTION 'V22_SESSION_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM photo.collections c WHERE c.tenant_id=p_tenant
  AND c.project_id=p_project AND c.id=p_collection) OR
  NOT photo.v22_session_policy_ready(p_tenant,p_project,p_policy,p_model_lock_sha) THEN
  RAISE EXCEPTION 'V22_SESSION_POLICY_UNAVAILABLE' USING ERRCODE='23514';
 END IF;
 INSERT INTO photo.shoot_sessions(tenant_id,project_id,collection_id,name,state,
  policy,capture_policy,consent_epoch)
 VALUES(p_tenant,p_project,p_collection,p_name,'open',p_policy,p_capture_policy,1)
 RETURNING * INTO created;
 PERFORM photo.ensure_v22_photographer_grant(p_tenant,p_project,p_actor);
 RETURN jsonb_build_object('id',created.id,'revision',created.revision::text,
  'state',created.state);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.create_v22_session(uuid,uuid,uuid,text,jsonb,jsonb,text,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.create_v22_session(uuid,uuid,uuid,text,jsonb,jsonb,text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.create_v22_session(uuid,uuid,uuid,text,jsonb,jsonb,text,uuid,uuid) TO photo_api;

-- +goose StatementBegin
CREATE FUNCTION photo.update_v22_session(p_tenant uuid,p_project uuid,p_id uuid,
 p_expected bigint,p_name text,p_state text,p_policy jsonb,p_capture_policy jsonb,
 p_model_lock_sha text,p_actor uuid,p_session uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE current_row photo.shoot_sessions%ROWTYPE; changed photo.shoot_sessions%ROWTYPE;
BEGIN
 IF p_tenant IS NULL OR p_project IS NULL OR p_id IS NULL OR p_expected IS NULL
  OR p_expected<1 OR length(coalesce(p_name,'')) NOT BETWEEN 1 AND 200 OR
  coalesce(p_state,'') NOT IN('open','closed','archived') OR
  (p_capture_policy IS NOT NULL AND (jsonb_typeof(p_capture_policy)<>'object'
   OR octet_length(p_capture_policy::text)>1048576)) THEN
  RAISE EXCEPTION 'V22_SESSION_INVALID' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND OR NOT photo.v2_editor_authorized(p_tenant,p_project,p_actor,p_session) THEN
  RAISE EXCEPTION 'V22_SESSION_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT * INTO current_row FROM photo.shoot_sessions WHERE tenant_id=p_tenant
  AND project_id=p_project AND id=p_id FOR UPDATE;
 IF current_row.id IS NULL THEN
  RAISE EXCEPTION 'V22_SESSION_NOT_FOUND' USING ERRCODE='P0002';
 END IF;
 IF current_row.revision<>p_expected OR current_row.state='archived' OR
  (current_row.state='open' AND p_state='archived') THEN
  RAISE EXCEPTION 'V22_SESSION_REVISION_CONFLICT' USING ERRCODE='40001';
 END IF;
 IF NOT photo.v22_session_policy_ready(p_tenant,p_project,p_policy,p_model_lock_sha) THEN
  RAISE EXCEPTION 'V22_SESSION_POLICY_UNAVAILABLE' USING ERRCODE='23514';
 END IF;
 UPDATE photo.shoot_sessions SET name=p_name,state=p_state,policy=p_policy,
  capture_policy=p_capture_policy WHERE tenant_id=p_tenant AND id=p_id
 RETURNING * INTO changed;
 RETURN jsonb_build_object('id',changed.id,'revision',changed.revision::text,
  'state',changed.state);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.update_v22_session(uuid,uuid,uuid,bigint,text,text,jsonb,jsonb,text,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.update_v22_session(uuid,uuid,uuid,bigint,text,text,jsonb,jsonb,text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.update_v22_session(uuid,uuid,uuid,bigint,text,text,jsonb,jsonb,text,uuid,uuid) TO photo_api;

-- Source: 00197_person_mutations.sql
-- A person is local to one project. Creation does not infer an identity or
-- grant consent; both person-scoped grants start revoked at epoch one.
-- +goose StatementBegin
CREATE FUNCTION photo.create_v22_person(p_tenant uuid,p_project uuid,p_label text,
 p_actor uuid,p_session uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE created photo.project_persons%ROWTYPE;
BEGIN
 IF p_tenant IS NULL OR p_project IS NULL OR p_actor IS NULL OR p_session IS NULL
  OR length(coalesce(p_label,'')) NOT BETWEEN 1 AND 120 THEN
  RAISE EXCEPTION 'V22_PERSON_INVALID' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND OR NOT photo.v2_editor_authorized(p_tenant,p_project,p_actor,p_session) THEN
  RAISE EXCEPTION 'V22_PERSON_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 INSERT INTO photo.project_persons(tenant_id,project_id,label,state,consent_epoch)
 VALUES(p_tenant,p_project,p_label,'active',1) RETURNING * INTO created;
 INSERT INTO photo.consent_grants(tenant_id,project_id,purpose,person_id,status,
  epoch,policy_version,actor_id)
 VALUES
  (p_tenant,p_project,'identity_matching',created.id,'revoked',1,'v2.2',p_actor),
  (p_tenant,p_project,'learning_person',created.id,'revoked',1,'v2.2',p_actor);
 PERFORM photo.ensure_v22_photographer_grant(p_tenant,p_project,p_actor);
 RETURN jsonb_build_object('id',created.id,'revision',created.revision::text,
  'state',created.state);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.create_v22_person(uuid,uuid,text,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.create_v22_person(uuid,uuid,text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.create_v22_person(uuid,uuid,text,uuid,uuid) TO photo_api;

-- +goose StatementBegin
CREATE FUNCTION photo.revoke_v22_person(p_tenant uuid,p_project uuid,p_person uuid,
 p_expected bigint,p_actor uuid,p_session uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE current_row photo.project_persons%ROWTYPE; changed photo.project_persons%ROWTYPE;
 grant_row record; event_id uuid;
BEGIN
 IF p_tenant IS NULL OR p_project IS NULL OR p_person IS NULL OR p_actor IS NULL
  OR p_session IS NULL OR p_expected IS NULL OR p_expected<1 THEN
  RAISE EXCEPTION 'V22_PERSON_INVALID' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM photo.authorize_tenant(
  p_actor,p_session,p_tenant) a WHERE a.role='owner') THEN
  RAISE EXCEPTION 'V22_PERSON_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT * INTO current_row FROM photo.project_persons p WHERE p.tenant_id=p_tenant
  AND p.project_id=p_project AND p.id=p_person FOR UPDATE;
 IF current_row.id IS NULL THEN
  RAISE EXCEPTION 'V22_PERSON_NOT_FOUND' USING ERRCODE='P0002';
 END IF;
 IF current_row.revision<>p_expected OR current_row.state<>'active' OR
  current_row.consent_epoch>=9223372036854775806 THEN
  RAISE EXCEPTION 'V22_PERSON_REVISION_CONFLICT' USING ERRCODE='40001';
 END IF;
 FOR grant_row IN SELECT g.id,g.revision,g.purpose FROM photo.consent_grants g
  WHERE g.tenant_id=p_tenant AND g.project_id=p_project AND g.person_id=p_person
   AND g.status='granted' ORDER BY g.id LOOP
  PERFORM photo.change_v2_consent(p_tenant,p_project,grant_row.id,
   grant_row.revision,grant_row.purpose,p_person,'revoke','v2.2',p_actor,p_session);
 END LOOP;
 UPDATE photo.project_persons SET state='revoked',consent_epoch=consent_epoch+1
  WHERE tenant_id=p_tenant AND id=p_person RETURNING * INTO changed;
 event_id:=gen_random_uuid();
 INSERT INTO photo.outbox(tenant_id,event_id,destination,routing_key,payload)
 VALUES(p_tenant,event_id,'photo.events.v1','v2.person.revoked',
  jsonb_build_object('schema_version',1,'event_id',event_id,
   'type','v2.person.revoked','tenant_id',p_tenant,'project_id',p_project,
   'person_id',p_person,'consent_epoch',changed.consent_epoch));
 RETURN jsonb_build_object('id',changed.id,'revision',changed.revision::text,
  'state',changed.state,'consent_epoch',changed.consent_epoch::text);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.revoke_v22_person(uuid,uuid,uuid,bigint,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.revoke_v22_person(uuid,uuid,uuid,bigint,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.revoke_v22_person(uuid,uuid,uuid,bigint,uuid,uuid) TO photo_api;

-- Source: 00197_adoption_consent_gate.sql
-- Preserve the V21 adoption body as a private core and place the consent
-- epoch lock before its run/task locks. Existing callers keep the same API.
ALTER FUNCTION photo.adopt_v2_plan(uuid,uuid,integer,bigint,uuid,jsonb,text)
 RENAME TO adopt_v2_plan_core;
REVOKE ALL ON FUNCTION photo.adopt_v2_plan_core(uuid,uuid,integer,bigint,uuid,jsonb,text)
 FROM photo_scheduler;

-- The last adopted descriptor atomically opens the late-bound plan barrier.
-- The caller already owns the run lock in adopt_v2_plan_core. Finalization
-- cannot observe all adopted descriptors with a sealed graph between these
-- statements because both changes commit together.
-- +goose StatementBegin
CREATE FUNCTION photo.open_v22_session_plan_barrier(p_tenant uuid,p_task uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_run uuid; v_count integer;
BEGIN
 SELECT t.run_id INTO v_run FROM photo.tasks t
 JOIN photo.v2_workflows w ON w.tenant_id=t.tenant_id AND w.run_id=t.run_id
 JOIN photo.runs r ON r.tenant_id=t.tenant_id AND r.id=t.run_id
 WHERE t.tenant_id=p_tenant AND t.id=p_task AND t.operation='session.describe'
  AND w.workflow_type='session' AND w.renderer_version='v2.2'
  AND r.kind='v2' AND r.status='running' AND r.graph_sealed
  AND NOT r.cancel_requested;
 IF v_run IS NULL THEN RETURN false; END IF;
 SELECT count(*) INTO v_count FROM photo.tasks t WHERE t.tenant_id=p_tenant
  AND t.run_id=v_run AND t.operation='session.describe';
 IF v_count NOT BETWEEN 1 AND 40 OR EXISTS(
  SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=v_run
   AND t.operation NOT IN ('session.describe','session.plan')) THEN
  RAISE EXCEPTION 'V22_SESSION_GRAPH_INVALID' USING ERRCODE='23514';
 END IF;
 IF EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant
  AND t.run_id=v_run AND t.operation='session.plan') OR EXISTS(
  SELECT 1 FROM photo.graph_expansions e WHERE e.tenant_id=p_tenant
   AND e.run_id=v_run AND e.kind='v2.session.plan/1') THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant
  AND t.run_id=v_run AND t.operation='session.describe' AND
  (t.state<>'succeeded' OR t.canonical_result_id IS NULL OR NOT EXISTS(
   SELECT 1 FROM photo.inbox i WHERE i.tenant_id=p_tenant
    AND i.consumer='v2-adopt' AND
    i.event_id=photo.v2_adoption_event_id(t.id,t.canonical_result_id)))) THEN RETURN false; END IF;
 INSERT INTO photo.graph_expansions(tenant_id,run_id,parent_task_id,kind,state,expected_count)
 VALUES(p_tenant,v_run,p_task,'v2.session.plan/1','open',1);
 UPDATE photo.runs SET graph_sealed=false WHERE tenant_id=p_tenant AND id=v_run
  AND status='running' AND graph_sealed AND NOT cancel_requested;
 IF NOT FOUND THEN RAISE EXCEPTION 'V22_SESSION_BARRIER_RACE' USING ERRCODE='40001'; END IF;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.open_v22_session_plan_barrier(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.open_v22_session_plan_barrier(uuid,uuid) FROM PUBLIC;

-- +goose StatementBegin
CREATE FUNCTION photo.adopt_v2_plan(p_tenant uuid,p_task uuid,p_attempt integer,p_fence bigint,
 p_result uuid,p_inventory jsonb,p_digest text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_run_id uuid; v_workflow_id uuid; v_project_id uuid; link record;
 current_status text; current_epoch bigint; v_adopted boolean;
BEGIN
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT t.run_id,w.id,w.project_id INTO v_run_id,v_workflow_id,v_project_id
  FROM photo.tasks t JOIN photo.v2_workflows w
   ON w.tenant_id=t.tenant_id AND w.run_id=t.run_id
  WHERE t.tenant_id=p_tenant AND t.id=p_task;
 IF v_workflow_id IS NULL THEN RETURN false; END IF;
 FOR link IN SELECT l.consent_id,l.consent_epoch FROM photo.workflow_consent_links l
  WHERE l.tenant_id=p_tenant AND l.project_id=v_project_id AND l.workflow_id=v_workflow_id
  ORDER BY l.consent_id LOOP
  SELECT g.status,g.epoch INTO current_status,current_epoch FROM photo.consent_grants g
   WHERE g.tenant_id=p_tenant AND g.project_id=v_project_id AND g.id=link.consent_id
   FOR UPDATE;
  IF current_status IS DISTINCT FROM 'granted' OR
   current_epoch IS DISTINCT FROM link.consent_epoch THEN RETURN false; END IF;
 END LOOP;
 v_adopted:=photo.adopt_v2_plan_core(p_tenant,p_task,p_attempt,p_fence,p_result,p_inventory,p_digest);
 IF v_adopted THEN PERFORM photo.open_v22_session_plan_barrier(p_tenant,p_task); END IF;
 RETURN v_adopted;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.adopt_v2_plan(uuid,uuid,integer,bigint,uuid,jsonb,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.adopt_v2_plan(uuid,uuid,integer,bigint,uuid,jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.adopt_v2_plan(uuid,uuid,integer,bigint,uuid,jsonb,text)
 TO photo_scheduler;

-- Seal must perform the same epoch check: a revoked draft cannot enter queue.
ALTER FUNCTION photo.seal_v2_graph(uuid,uuid) RENAME TO seal_v2_graph_core;
REVOKE ALL ON FUNCTION photo.seal_v2_graph_core(uuid,uuid) FROM photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.seal_v2_graph(p_tenant uuid,p_run uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_workflow_id uuid; v_project_id uuid; link record;
 current_status text; current_epoch bigint;
BEGIN
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT w.id,w.project_id INTO v_workflow_id,v_project_id FROM photo.v2_workflows w
  WHERE w.tenant_id=p_tenant AND w.run_id=p_run;
 IF v_workflow_id IS NULL THEN RETURN false; END IF;
 FOR link IN SELECT l.consent_id,l.consent_epoch FROM photo.workflow_consent_links l
  WHERE l.tenant_id=p_tenant AND l.project_id=v_project_id AND l.workflow_id=v_workflow_id
  ORDER BY l.consent_id LOOP
  SELECT g.status,g.epoch INTO current_status,current_epoch FROM photo.consent_grants g
   WHERE g.tenant_id=p_tenant AND g.project_id=v_project_id AND g.id=link.consent_id
   FOR UPDATE;
  IF current_status IS DISTINCT FROM 'granted' OR
   current_epoch IS DISTINCT FROM link.consent_epoch THEN RETURN false; END IF;
 END LOOP;
 RETURN photo.seal_v2_graph_core(p_tenant,p_run);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.seal_v2_graph(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.seal_v2_graph(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.seal_v2_graph(uuid,uuid) TO photo_scheduler;

-- Source: 00197_session_plan_inputs.sql
-- Trusted compiler input: only canonical, adopted descriptor roots are
-- returned, in frozen shard order. No future output reference is fabricated.
-- +goose StatementBegin
CREATE FUNCTION photo.v22_session_plan_inputs(p_tenant uuid,p_run uuid)
RETURNS TABLE(task_id uuid,artifact_id uuid,sha256 text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_count integer; v_ready integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM photo.runs r JOIN photo.v2_workflows w
  ON w.tenant_id=r.tenant_id AND w.run_id=r.id
  JOIN photo.tenants tenant ON tenant.id=r.tenant_id
  WHERE r.tenant_id=p_tenant AND r.id=p_run AND r.kind='v2'
   AND r.status='running' AND NOT r.cancel_requested AND NOT r.graph_sealed
   AND w.workflow_type='session' AND w.renderer_version='v2.2'
   AND tenant.status='active' AND EXISTS(SELECT 1 FROM photo.graph_expansions e
    WHERE e.tenant_id=p_tenant AND e.run_id=p_run
     AND e.kind='v2.session.plan/1' AND e.state='open')) THEN RETURN; END IF;
 SELECT count(*) INTO v_count FROM photo.tasks t WHERE t.tenant_id=p_tenant
  AND t.run_id=p_run AND t.operation='session.describe';
 IF v_count NOT BETWEEN 1 AND 40 OR EXISTS(SELECT 1 FROM photo.tasks t
  WHERE t.tenant_id=p_tenant AND t.run_id=p_run AND t.operation='session.describe'
   AND t.node_key !~ '^session[.]describe:(0|[1-9]|[1-3][0-9])$') THEN RETURN; END IF;
 SELECT count(*) INTO v_ready FROM photo.tasks t
  JOIN photo.task_results z ON z.tenant_id=t.tenant_id
   AND z.task_id=t.id AND z.id=t.canonical_result_id
   AND z.attempt=t.attempt AND z.fencing_token=t.fencing_token
  JOIN photo.artifacts a ON a.tenant_id=t.tenant_id
   AND a.id=(z.outputs->0->>'artifact_id')::uuid
   AND a.sha256=z.outputs->0->>'sha256'
   AND a.state='ready' AND a.verified_at IS NOT NULL
   AND a.object_version IS NOT NULL
   AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp())
  WHERE t.tenant_id=p_tenant AND t.run_id=p_run AND t.operation='session.describe'
   AND t.state='succeeded' AND jsonb_typeof(z.outputs)='array'
   AND jsonb_array_length(z.outputs)=1 AND a.output_role='document'
   AND a.created_by_task_id=t.id AND a.produced_attempt=t.attempt
   AND a.produced_fence=t.fencing_token
   AND EXISTS(SELECT 1 FROM photo.inbox i WHERE i.tenant_id=p_tenant
    AND i.consumer='v2-adopt'
    AND i.event_id=photo.v2_adoption_event_id(t.id,t.canonical_result_id))
   AND (split_part(t.node_key,':',2))::integer BETWEEN 0 AND v_count-1;
 IF v_ready<>v_count OR EXISTS(SELECT 1 FROM photo.tasks t
  WHERE t.tenant_id=p_tenant AND t.run_id=p_run AND t.operation='session.describe'
  GROUP BY split_part(t.node_key,':',2) HAVING count(*)<>1) THEN RETURN; END IF;
 RETURN QUERY SELECT t.id,a.id,a.sha256 FROM photo.tasks t
  JOIN photo.task_results z ON z.tenant_id=t.tenant_id
   AND z.task_id=t.id AND z.id=t.canonical_result_id
  JOIN photo.artifacts a ON a.tenant_id=t.tenant_id
   AND a.id=(z.outputs->0->>'artifact_id')::uuid
  WHERE t.tenant_id=p_tenant AND t.run_id=p_run AND t.operation='session.describe'
  ORDER BY (split_part(t.node_key,':',2))::integer;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_session_plan_inputs(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_session_plan_inputs(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v22_session_plan_inputs(uuid,uuid) TO photo_scheduler;

-- Source: 00197_session_plan_lease.sql
-- Claim only a session barrier whose descriptor outputs are all canonical and
-- adopted. The token fences concurrent compiler instances and is renewable.
-- +goose StatementBegin
CREATE FUNCTION photo.claim_v22_session_plan()
RETURNS TABLE(expansion_id uuid,lease_token uuid,lease_until timestamptz,
 tenant_id uuid,run_id uuid,workflow_id uuid)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE hint photo.graph_expansions%ROWTYPE; e photo.graph_expansions%ROWTYPE;
 r photo.runs%ROWTYPE; v_count integer; v_ready integer;
 fence uuid:=gen_random_uuid(); until_time timestamptz;
BEGIN
 SELECT x.* INTO hint FROM photo.graph_expansions x
 JOIN photo.runs rr ON rr.tenant_id=x.tenant_id AND rr.id=x.run_id
 JOIN photo.v2_workflows w ON w.tenant_id=x.tenant_id AND w.run_id=x.run_id
 JOIN photo.tenants tenant ON tenant.id=x.tenant_id
 WHERE x.kind='v2.session.plan/1' AND x.state='open'
  AND x.next_expansion_at<=clock_timestamp()
  AND (x.expansion_lease_until IS NULL OR x.expansion_lease_until<=clock_timestamp())
  AND rr.kind='v2' AND rr.status='running' AND NOT rr.cancel_requested
  AND NOT rr.graph_sealed AND w.workflow_type='session'
  AND w.renderer_version='v2.2' AND tenant.status='active'
 ORDER BY x.next_expansion_at,x.created_at,x.id LIMIT 1;
 IF NOT FOUND THEN RETURN; END IF;
 SELECT rr.* INTO r FROM photo.runs rr WHERE rr.tenant_id=hint.tenant_id
  AND rr.id=hint.run_id FOR UPDATE SKIP LOCKED;
 IF NOT FOUND OR r.cancel_requested OR r.status<>'running' OR r.graph_sealed THEN RETURN; END IF;
 SELECT x.* INTO e FROM photo.graph_expansions x WHERE x.tenant_id=hint.tenant_id
  AND x.id=hint.id AND x.run_id=r.id FOR UPDATE SKIP LOCKED;
 IF NOT FOUND OR e.kind<>'v2.session.plan/1' OR e.state<>'open'
  OR e.next_expansion_at>clock_timestamp() OR
  (e.expansion_lease_until IS NOT NULL AND e.expansion_lease_until>clock_timestamp()) THEN RETURN; END IF;
 SELECT count(*) INTO v_count FROM photo.tasks t WHERE t.tenant_id=e.tenant_id
  AND t.run_id=e.run_id AND t.operation='session.describe';
 SELECT count(*) INTO v_ready FROM photo.v22_session_plan_inputs(e.tenant_id,e.run_id);
 IF v_count NOT BETWEEN 1 AND 40 OR v_ready<>v_count THEN RETURN; END IF;
 until_time:=clock_timestamp()+interval '60 seconds';
 UPDATE photo.graph_expansions x SET expansion_token=fence,expansion_lease_until=until_time
  WHERE x.tenant_id=e.tenant_id AND x.id=e.id;
 RETURN QUERY SELECT e.id,fence,until_time,e.tenant_id,e.run_id,w.id
  FROM photo.v2_workflows w WHERE w.tenant_id=e.tenant_id AND w.run_id=e.run_id;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.claim_v22_session_plan() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.claim_v22_session_plan() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.claim_v22_session_plan() TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.renew_v22_session_plan(p_expansion uuid,p_token uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE hint photo.graph_expansions%ROWTYPE; r photo.runs%ROWTYPE;
BEGIN
 IF p_token IS NULL THEN RETURN false; END IF;
 SELECT * INTO hint FROM photo.graph_expansions WHERE id=p_expansion;
 IF NOT FOUND OR hint.kind<>'v2.session.plan/1' THEN RETURN false; END IF;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=hint.tenant_id
  AND id=hint.run_id FOR UPDATE;
 IF NOT FOUND OR r.cancel_requested OR r.status<>'running' OR r.graph_sealed THEN RETURN false; END IF;
 UPDATE photo.graph_expansions SET expansion_lease_until=clock_timestamp()+interval '60 seconds'
 WHERE tenant_id=hint.tenant_id AND id=hint.id AND run_id=hint.run_id
  AND kind='v2.session.plan/1' AND state='open'
  AND expansion_token=p_token AND expansion_lease_until>clock_timestamp();
 RETURN FOUND;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.renew_v22_session_plan(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.renew_v22_session_plan(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.renew_v22_session_plan(uuid,uuid) TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.release_v22_session_plan(p_expansion uuid,p_token uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE hint photo.graph_expansions%ROWTYPE;
BEGIN
 IF p_token IS NULL THEN RETURN false; END IF;
 SELECT * INTO hint FROM photo.graph_expansions WHERE id=p_expansion;
 IF NOT FOUND OR hint.kind<>'v2.session.plan/1' THEN RETURN false; END IF;
 PERFORM id FROM photo.runs WHERE tenant_id=hint.tenant_id AND id=hint.run_id FOR UPDATE;
 UPDATE photo.graph_expansions SET expansion_token=NULL,expansion_lease_until=NULL,
  next_expansion_at=clock_timestamp()+interval '5 seconds'
 WHERE tenant_id=hint.tenant_id AND id=hint.id AND run_id=hint.run_id
  AND kind='v2.session.plan/1' AND state='open' AND expansion_token=p_token;
 RETURN FOUND;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.release_v22_session_plan(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.release_v22_session_plan(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.release_v22_session_plan(uuid,uuid) TO photo_scheduler;

-- Source: 00197_session_plan_documents.sql
-- One immutable params document is scoped to the open session expansion.
ALTER TABLE photo.backend_documents DROP CONSTRAINT backend_documents_purpose_check;
ALTER TABLE photo.backend_documents ADD CONSTRAINT backend_documents_purpose_check
 CHECK (purpose IN ('task_params','review_selection','v2_input_manifest',
                   'v2_session_plan_params') OR
  CASE WHEN purpose ~ '^v2_input_chunk_([0-9]|[1-9][0-9]{1,3})$'
   THEN substring(purpose from 16)::integer BETWEEN 0 AND 1953 ELSE false END);

-- +goose StatementBegin
CREATE FUNCTION photo.v22_session_plan_document_scope(p_tenant uuid,p_run uuid,p_owner uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT EXISTS(SELECT 1 FROM photo.graph_expansions e
  JOIN photo.runs r ON r.tenant_id=e.tenant_id AND r.id=e.run_id
  JOIN photo.v2_workflows w ON w.tenant_id=r.tenant_id AND w.run_id=r.id
  JOIN photo.tenants tenant ON tenant.id=r.tenant_id
  WHERE e.tenant_id=p_tenant AND e.run_id=p_run AND e.id=p_owner
   AND e.kind='v2.session.plan/1' AND e.state='open'
   AND e.expansion_token IS NOT NULL AND e.expansion_lease_until>clock_timestamp()
   AND r.kind='v2' AND r.status='running' AND NOT r.cancel_requested
   AND NOT r.graph_sealed AND w.workflow_type='session'
   AND w.renderer_version='v2.2' AND tenant.status='active');
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_session_plan_document_scope(uuid,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_session_plan_document_scope(uuid,uuid,uuid) FROM PUBLIC;

-- +goose StatementBegin
CREATE FUNCTION photo.reserve_v22_session_plan_document(p_tenant uuid,p_run uuid,
 p_owner uuid,p_purpose text,p_sha text,p_bytes bigint,p_bucket text)
RETURNS TABLE(outcome text,artifact_id uuid,token uuid,ready boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE d photo.backend_documents%ROWTYPE; capacity numeric; used numeric;
 aid uuid:=gen_random_uuid(); fence uuid:=gen_random_uuid();
BEGIN
 IF p_purpose IS DISTINCT FROM 'v2_session_plan_params' OR p_sha IS NULL
  OR p_sha !~ '^[0-9a-f]{64}$' OR p_bytes IS NULL OR p_bytes NOT BETWEEN 2 AND 1048576
  OR p_bucket IS NULL OR length(p_bucket) NOT BETWEEN 3 AND 63 THEN
  RAISE EXCEPTION 'INVALID_V22_PLAN_DOCUMENT' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 PERFORM id FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 PERFORM id FROM photo.graph_expansions WHERE tenant_id=p_tenant AND id=p_owner FOR UPDATE;
 IF NOT photo.v22_session_plan_document_scope(p_tenant,p_run,p_owner) THEN
  RETURN QUERY SELECT 'forbidden',NULL::uuid,NULL::uuid,false; RETURN;
 END IF;
 SELECT * INTO d FROM photo.backend_documents b WHERE b.tenant_id=p_tenant
  AND b.run_id=p_run AND b.owner_id=p_owner AND b.purpose=p_purpose FOR UPDATE;
 IF FOUND THEN
  IF d.sha256<>p_sha OR d.bytes<>p_bytes OR d.bucket<>p_bucket THEN
   RETURN QUERY SELECT 'conflict',NULL::uuid,NULL::uuid,false; RETURN;
  END IF;
  IF d.state='ready' THEN
   IF NOT EXISTS(SELECT 1 FROM photo.artifacts a WHERE a.tenant_id=d.tenant_id
    AND a.id=d.artifact_id AND a.state='ready' AND a.sha256=d.sha256
    AND a.object_version=d.object_version) THEN
    RETURN QUERY SELECT 'stale',NULL::uuid,NULL::uuid,false; RETURN;
   END IF;
   RETURN QUERY SELECT 'replayed',d.artifact_id,d.token,true; RETURN;
  END IF;
  IF d.state<>'pending' THEN
   RETURN QUERY SELECT 'stale',NULL::uuid,NULL::uuid,false; RETURN;
  END IF;
  UPDATE photo.backend_documents SET token=fence WHERE id=d.id;
  RETURN QUERY SELECT 'resumed',d.artifact_id,fence,false; RETURN;
 END IF;
 SELECT (quotas->>'storage_bytes')::numeric INTO capacity FROM photo.tenants WHERE id=p_tenant;
 SELECT storage_bytes::numeric+reserved_bytes INTO used FROM photo.tenant_usage WHERE tenant_id=p_tenant;
 IF capacity IS NULL OR used IS NULL OR used+p_bytes>capacity OR
  used+p_bytes>9007199254740991 THEN
  RETURN QUERY SELECT 'quota',NULL::uuid,NULL::uuid,false; RETURN;
 END IF;
 INSERT INTO photo.backend_documents(tenant_id,run_id,owner_id,purpose,
  artifact_id,token,sha256,bytes,bucket)
 VALUES(p_tenant,p_run,p_owner,p_purpose,aid,fence,p_sha,p_bytes,p_bucket);
 UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes+p_bytes WHERE tenant_id=p_tenant;
 RETURN QUERY SELECT 'created',aid,fence,false;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.reserve_v22_session_plan_document(uuid,uuid,uuid,text,text,bigint,text)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.reserve_v22_session_plan_document(uuid,uuid,uuid,text,text,bigint,text)
 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.reserve_v22_session_plan_document(uuid,uuid,uuid,text,text,bigint,text)
 TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.complete_v22_session_plan_document(p_tenant uuid,p_run uuid,
 p_owner uuid,p_purpose text,p_artifact uuid,p_token uuid,p_sha text,p_bytes bigint,
 p_bucket text,p_version text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE d photo.backend_documents%ROWTYPE; target text;
BEGIN
 IF p_purpose IS DISTINCT FROM 'v2_session_plan_params' OR p_token IS NULL OR
  p_version IS NULL OR p_version IN ('','null') OR length(p_version)>1024 THEN RETURN false; END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 PERFORM id FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 PERFORM id FROM photo.graph_expansions WHERE tenant_id=p_tenant AND id=p_owner FOR UPDATE;
 IF NOT photo.v22_session_plan_document_scope(p_tenant,p_run,p_owner) THEN RETURN false; END IF;
 SELECT * INTO d FROM photo.backend_documents b WHERE b.tenant_id=p_tenant
  AND b.run_id=p_run AND b.owner_id=p_owner AND b.purpose=p_purpose FOR UPDATE;
 IF d.id IS NULL OR d.artifact_id IS DISTINCT FROM p_artifact OR
  d.token IS DISTINCT FROM p_token OR d.sha256 IS DISTINCT FROM p_sha OR
  d.bytes IS DISTINCT FROM p_bytes OR d.bucket IS DISTINCT FROM p_bucket THEN RETURN false; END IF;
 IF d.state='ready' THEN
  RETURN d.object_version=p_version AND EXISTS(SELECT 1 FROM photo.artifacts a
   WHERE a.tenant_id=d.tenant_id AND a.id=d.artifact_id AND a.state='ready'
    AND a.sha256=d.sha256 AND a.object_version=p_version);
 END IF;
 IF d.state<>'pending' THEN RETURN false; END IF;
 target:='tenants/'||p_tenant||'/runs/'||p_run||'/documents/'||p_artifact;
 INSERT INTO photo.artifacts(id,tenant_id,bucket,object_key,object_version,sha256,
  bytes,media_type,state,verified_at,output_role)
 VALUES(d.artifact_id,d.tenant_id,d.bucket,target,p_version,d.sha256,d.bytes,
  'application/json','ready',clock_timestamp(),d.purpose);
 UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes-d.bytes,
  storage_bytes=storage_bytes+d.bytes
  WHERE tenant_id=d.tenant_id AND reserved_bytes>=d.bytes;
 IF NOT FOUND THEN RAISE EXCEPTION 'DOCUMENT_QUOTA_ACCOUNTING' USING ERRCODE='23514'; END IF;
 UPDATE photo.backend_documents SET state='ready',object_version=p_version,
  completed_at=clock_timestamp() WHERE id=d.id;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.complete_v22_session_plan_document(uuid,uuid,uuid,text,uuid,uuid,text,bigint,text,text)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.complete_v22_session_plan_document(uuid,uuid,uuid,text,uuid,uuid,text,bigint,text,text)
 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.complete_v22_session_plan_document(uuid,uuid,uuid,text,uuid,uuid,text,bigint,text,text)
 TO photo_scheduler;

-- Source: 00197_session_plan_stage.sql
-- Stage the late-bound plan node after its exact descriptor refs and params
-- document are ready. Input closure publication happens after this transaction.
-- +goose StatementBegin
CREATE FUNCTION photo.stage_v22_session_plan(p_tenant uuid,p_run uuid,
 p_expansion uuid,p_token uuid,p_task uuid,p_params uuid,p_params_sha text,
 p_input_digest text,p_shards jsonb,p_profile jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE; e photo.graph_expansions%ROWTYPE;
 w photo.v2_workflows%ROWTYPE; existing photo.tasks%ROWTYPE;
 expected jsonb; expected_id uuid; h bytea; descriptor record; shard_count integer;
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL OR p_expansion IS NULL OR p_token IS NULL
  OR p_task IS NULL OR p_params IS NULL OR p_params_sha !~ '^[0-9a-f]{64}$'
  OR p_input_digest !~ '^[0-9a-f]{64}$'
  OR jsonb_typeof(p_shards) IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_shards) NOT BETWEEN 1 AND 40
  OR jsonb_typeof(p_profile) IS DISTINCT FROM 'object'
  OR p_profile->>'backend' IS DISTINCT FROM 'cpu'
  OR p_profile->>'renderer_version' IS DISTINCT FROM 'v2.2'
  OR p_profile ? 'v2_input_manifest' THEN RETURN false; END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 SELECT * INTO e FROM photo.graph_expansions WHERE tenant_id=p_tenant
  AND id=p_expansion AND run_id=p_run FOR UPDATE;
 SELECT * INTO w FROM photo.v2_workflows WHERE tenant_id=p_tenant AND run_id=p_run;
 IF r.id IS NULL OR r.kind<>'v2' OR r.status<>'running' OR r.graph_sealed
  OR r.cancel_requested OR e.id IS NULL OR e.kind<>'v2.session.plan/1'
  OR e.state<>'open' OR e.expansion_token IS DISTINCT FROM p_token
  OR e.expansion_lease_until<=clock_timestamp()
  OR w.id IS NULL OR w.workflow_type<>'session' OR w.renderer_version<>'v2.2'
  OR NOT EXISTS(SELECT 1 FROM photo.tenants tenant WHERE tenant.id=p_tenant
   AND tenant.status='active') THEN RETURN false; END IF;
 h:=public.digest(uuid_send(w.id)||convert_to('session.plan:0','UTF8'),'sha1');
 h:=set_byte(h,6,(get_byte(h,6)&15)|80);
 h:=set_byte(h,8,(get_byte(h,8)&63)|128);
 expected_id:=encode(substring(h FROM 1 FOR 16),'hex')::uuid;
 IF p_task<>expected_id OR NOT EXISTS(SELECT 1 FROM photo.operation_registry op
  WHERE op.operation='session.plan' AND op.version='1'
   AND op.resource_class='cpu' AND op.backends ? 'cpu')
  OR NOT EXISTS(SELECT 1 FROM photo.backend_documents d
   JOIN photo.artifacts a ON a.tenant_id=d.tenant_id AND a.id=d.artifact_id
   WHERE d.tenant_id=p_tenant AND d.run_id=p_run AND d.owner_id=p_expansion
    AND d.purpose='v2_session_plan_params' AND d.state='ready'
    AND d.artifact_id=p_params AND d.sha256=p_params_sha
    AND a.sha256=d.sha256 AND a.state='ready' AND a.media_type='application/json'
    AND a.object_version=d.object_version AND a.verified_at IS NOT NULL
    AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp())) THEN RETURN false; END IF;
 SELECT jsonb_agg(jsonb_build_object('artifact_id',x.artifact_id,'sha256',x.sha256)
  ORDER BY x.pos),count(*) INTO expected,shard_count
 FROM photo.v22_session_plan_inputs(p_tenant,p_run) WITH ORDINALITY
  x(task_id,artifact_id,sha256,pos);
 IF shard_count<>jsonb_array_length(p_shards) OR expected IS DISTINCT FROM p_shards
  THEN RETURN false; END IF;
 SELECT * INTO existing FROM photo.tasks WHERE tenant_id=p_tenant AND run_id=p_run
  AND node_key='session.plan:0' FOR UPDATE;
 IF existing.id IS NOT NULL THEN
  RETURN existing.id=p_task AND existing.operation='session.plan'
   AND existing.operation_version='1' AND existing.resource_class='cpu'
   AND existing.params_artifact_id=p_params AND existing.input_digest=p_input_digest
   AND (existing.execution_profile-'v2_input_manifest'-'v2_entry_count'
    -'v2_entries_sha'-'contracts_sha')=p_profile AND existing.state='blocked';
 END IF;
 IF EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant
  AND t.run_id=p_run AND t.operation NOT IN ('session.describe')) THEN RETURN false; END IF;
 INSERT INTO photo.tasks(id,tenant_id,run_id,node_key,operation,
  operation_version,resource_class,inputs,params_artifact_id,input_digest,execution_profile)
 VALUES(p_task,p_tenant,p_run,'session.plan:0','session.plan','1','cpu',
  '[]'::jsonb,p_params,p_input_digest,p_profile);
 FOR descriptor IN SELECT task_id FROM photo.v22_session_plan_inputs(p_tenant,p_run) LOOP
  INSERT INTO photo.task_edges(tenant_id,run_id,prerequisite_id,dependent_id,condition)
  VALUES(p_tenant,p_run,descriptor.task_id,p_task,'success');
 END LOOP;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.stage_v22_session_plan(uuid,uuid,uuid,uuid,uuid,uuid,text,text,jsonb,jsonb)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.stage_v22_session_plan(uuid,uuid,uuid,uuid,uuid,uuid,text,text,jsonb,jsonb)
 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.stage_v22_session_plan(uuid,uuid,uuid,uuid,uuid,uuid,text,text,jsonb,jsonb)
 TO photo_scheduler;

-- Source: 00197_session_plan_close.sql
-- Close the session expansion only after the plan task's transport closure
-- proves every adopted descriptor is among its exact typed inputs.
-- +goose StatementBegin
CREATE FUNCTION photo.close_v22_session_plan(p_tenant uuid,p_run uuid,
 p_expansion uuid,p_token uuid,p_task uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE; e photo.graph_expansions%ROWTYPE;
 t photo.tasks%ROWTYPE; descriptor record; descriptor_count integer;
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL OR p_expansion IS NULL OR
  p_token IS NULL OR p_task IS NULL THEN RETURN false; END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 SELECT * INTO e FROM photo.graph_expansions WHERE tenant_id=p_tenant
  AND run_id=p_run AND id=p_expansion FOR UPDATE;
 SELECT * INTO t FROM photo.tasks WHERE tenant_id=p_tenant AND run_id=p_run
  AND id=p_task FOR UPDATE;
 IF r.id IS NULL OR r.kind<>'v2' OR r.status<>'running' OR r.graph_sealed
  OR r.cancel_requested OR e.id IS NULL OR e.kind<>'v2.session.plan/1'
  OR e.state<>'open' OR e.expansion_token IS DISTINCT FROM p_token
  OR e.expansion_lease_until<=clock_timestamp() OR t.id IS NULL
  OR t.node_key<>'session.plan:0' OR t.operation<>'session.plan'
  OR t.operation_version<>'1' OR t.resource_class<>'cpu'
  OR t.state<>'blocked' OR t.attempt<>0 OR t.cancel_requested
  OR NOT photo.v2_input_closure_ready(p_task)
  OR NOT EXISTS(SELECT 1 FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant
   AND w.run_id=p_run AND w.workflow_type='session' AND w.renderer_version='v2.2')
  OR NOT EXISTS(SELECT 1 FROM photo.operation_registry op WHERE op.operation='session.plan'
   AND op.version='1' AND op.resource_class='cpu' AND op.v2_enabled
   AND op.backends ? 'cpu') THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM photo.backend_documents d
  WHERE d.tenant_id=p_tenant AND d.run_id=p_run AND d.owner_id=p_expansion
   AND d.purpose='v2_session_plan_params' AND d.state='ready'
   AND d.artifact_id=t.params_artifact_id)
  OR NOT EXISTS(SELECT 1 FROM photo.v2_task_inputs i
   WHERE i.tenant_id=p_tenant AND i.task_id=p_task
    AND i.artifact_id=t.params_artifact_id AND i.contract='Params')
  OR (SELECT count(*) FROM photo.v2_task_inputs i WHERE i.tenant_id=p_tenant
   AND i.task_id=p_task AND i.contract='SessionPlanContext')<>1 THEN RETURN false; END IF;
 SELECT count(*) INTO descriptor_count FROM photo.v22_session_plan_inputs(p_tenant,p_run);
 IF descriptor_count NOT BETWEEN 1 AND 40 OR
  (SELECT count(*) FROM photo.v2_task_inputs i WHERE i.tenant_id=p_tenant
   AND i.task_id=p_task AND i.contract='DescriptorShard')<>descriptor_count
  OR (SELECT count(*) FROM photo.task_edges edge WHERE edge.tenant_id=p_tenant
   AND edge.run_id=p_run AND edge.dependent_id=p_task)<>descriptor_count THEN RETURN false; END IF;
 FOR descriptor IN SELECT * FROM photo.v22_session_plan_inputs(p_tenant,p_run) LOOP
  IF NOT EXISTS(SELECT 1 FROM photo.v2_task_inputs i WHERE i.tenant_id=p_tenant
   AND i.task_id=p_task AND i.artifact_id=descriptor.artifact_id
   AND i.sha256=descriptor.sha256 AND i.contract='DescriptorShard')
   OR NOT EXISTS(SELECT 1 FROM photo.task_edges edge WHERE edge.tenant_id=p_tenant
    AND edge.run_id=p_run AND edge.prerequisite_id=descriptor.task_id
    AND edge.dependent_id=p_task AND edge.condition='success') THEN RETURN false; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM photo.graph_expansions other WHERE other.tenant_id=p_tenant
  AND other.run_id=p_run AND other.id<>p_expansion AND other.state<>'closed') THEN RETURN false; END IF;
 UPDATE photo.graph_expansions SET state='closed',cursor='1',
  expansion_token=NULL,expansion_lease_until=NULL
  WHERE tenant_id=p_tenant AND id=p_expansion AND state='open'
   AND expansion_token=p_token;
 IF NOT FOUND THEN RAISE EXCEPTION 'V22_PLAN_EXPANSION_RACE' USING ERRCODE='40001'; END IF;
 UPDATE photo.runs SET graph_sealed=true,revision=revision+1
  WHERE tenant_id=p_tenant AND id=p_run AND status='running'
   AND NOT cancel_requested AND NOT graph_sealed AND revision<9007199254740991;
 IF NOT FOUND THEN RAISE EXCEPTION 'V22_PLAN_SEAL_RACE' USING ERRCODE='40001'; END IF;
 IF NOT photo.activate_bound_task(p_task,t.input_digest,t.params_artifact_id) THEN
  RAISE EXCEPTION 'V22_PLAN_ACTIVATION_FAILED' USING ERRCODE='23514';
 END IF;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.close_v22_session_plan(uuid,uuid,uuid,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.close_v22_session_plan(uuid,uuid,uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.close_v22_session_plan(uuid,uuid,uuid,uuid,uuid)
 TO photo_scheduler;

-- Source: 00197_session_plan_frozen.sql
-- The plan compiler reads only admission-pinned configuration. A mutable
-- shoot_sessions row or current collection membership is never consulted.
-- +goose StatementBegin
CREATE FUNCTION photo.v22_session_plan_frozen(p_tenant uuid,p_run uuid)
RETURNS TABLE(item_count integer,policy jsonb,policy_sha text,
 context_artifact_id uuid,context_sha text,snapshot_digest text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE config jsonb; context_id uuid; context_digest text;
BEGIN
 SELECT r.config_snapshot->'v22_session_plan' INTO config FROM photo.runs r
 JOIN photo.v2_workflows w ON w.tenant_id=r.tenant_id AND w.run_id=r.id
 JOIN photo.snapshots s ON s.tenant_id=r.tenant_id AND s.id=r.input_snapshot_id
 JOIN photo.tenants tenant ON tenant.id=r.tenant_id
 WHERE r.tenant_id=p_tenant AND r.id=p_run AND r.kind='v2'
  AND r.status='running' AND NOT r.cancel_requested AND NOT r.graph_sealed
  AND w.workflow_type='session' AND w.renderer_version='v2.2'
  AND w.input_snapshot_id=s.id AND w.project_id=(r.config_snapshot->>'project_id')::uuid
  AND s.kind='v2' AND s.principal_type='user' AND s.principal_id=r.created_by
  AND s.item_count BETWEEN 1 AND 5000 AND tenant.status='active'
  AND EXISTS(SELECT 1 FROM photo.graph_expansions e WHERE e.tenant_id=p_tenant
   AND e.run_id=p_run AND e.kind='v2.session.plan/1' AND e.state='open')
  AND jsonb_typeof(r.config_snapshot->'v22_session_plan')='object';
 IF config IS NULL OR (config-'schema_version'-'item_count'-'snapshot_digest'
  -'policy'-'context_sha')<>'{}'::jsonb
  OR config->>'schema_version'<>'1'
  OR coalesce(config->>'item_count','') !~ '^[1-9][0-9]{0,3}$'
  OR coalesce(config->>'snapshot_digest','') !~ '^[0-9a-f]{64}$'
  OR jsonb_typeof(config->'policy')<>'object'
  OR coalesce(config->>'context_sha','') !~ '^[0-9a-f]{64}$'
  OR NOT EXISTS(SELECT 1 FROM photo.runs r JOIN photo.snapshots s
   ON s.tenant_id=r.tenant_id AND s.id=r.input_snapshot_id
   WHERE r.tenant_id=p_tenant AND r.id=p_run
    AND s.item_count=(config->>'item_count')::integer
    AND s.digest=config->>'snapshot_digest') THEN RETURN; END IF;
 SELECT d.artifact_id,d.sha256 INTO context_id,context_digest
 FROM photo.backend_documents d JOIN photo.artifacts a
  ON a.tenant_id=d.tenant_id AND a.id=d.artifact_id
 WHERE d.tenant_id=p_tenant AND d.run_id=p_run AND d.owner_id=p_run
  AND d.purpose='v2_analysis_context' AND d.state='ready'
  AND d.sha256=config->>'context_sha' AND a.sha256=d.sha256
  AND a.state='ready' AND a.media_type='application/json'
  AND a.verified_at IS NOT NULL AND a.object_version=d.object_version
  AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp());
 IF context_id IS NULL THEN RETURN; END IF;
 RETURN QUERY SELECT (config->>'item_count')::integer,config->'policy',w.policy_sha,
  context_id,context_digest,config->>'snapshot_digest'
 FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant AND w.run_id=p_run;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_session_plan_frozen(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_session_plan_frozen(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v22_session_plan_frozen(uuid,uuid) TO photo_scheduler;

-- Source: 00197_consent_mutations.sql
-- V22 grant/revoke boundary. V23 extends the same entrypoint to disable
-- dependent learning versions and enqueue artifact cleanup before release.
-- +goose StatementBegin
CREATE FUNCTION photo.change_v2_consent(p_tenant uuid,p_project uuid,p_consent uuid,
 p_expected bigint,p_purpose text,p_person uuid,p_action text,p_policy_version text,
 p_actor uuid,p_session uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE grant_row photo.consent_grants%ROWTYPE; changed photo.consent_grants%ROWTYPE;
 dependent record; run_row photo.runs%ROWTYPE; task_row record; next_status text;
 event_id uuid;
BEGIN
 IF p_tenant IS NULL OR p_project IS NULL OR p_consent IS NULL OR p_actor IS NULL
  OR p_session IS NULL OR p_expected IS NULL OR p_expected<1 OR
  coalesce(p_action,'') NOT IN('grant','revoke') OR
  length(coalesce(p_policy_version,'')) NOT BETWEEN 1 AND 80 THEN
  RAISE EXCEPTION 'V22_CONSENT_INVALID' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM photo.authorize_tenant(
  p_actor,p_session,p_tenant) a WHERE a.role='owner') OR
  NOT EXISTS(SELECT 1 FROM photo.projects p WHERE p.tenant_id=p_tenant
   AND p.id=p_project AND p.archived_at IS NULL) THEN
  RAISE EXCEPTION 'V22_CONSENT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT * INTO grant_row FROM photo.consent_grants g WHERE g.tenant_id=p_tenant
  AND g.project_id=p_project AND g.id=p_consent FOR UPDATE;
 IF grant_row.id IS NULL THEN
  RAISE EXCEPTION 'V22_CONSENT_NOT_FOUND' USING ERRCODE='P0002';
 END IF;
 IF grant_row.revision<>p_expected OR grant_row.purpose IS DISTINCT FROM p_purpose OR
  grant_row.person_id IS DISTINCT FROM p_person OR
  grant_row.epoch>=9223372036854775806 OR
  (p_action='grant' AND grant_row.status<>'revoked') OR
  (p_action='revoke' AND grant_row.status<>'granted') THEN
  RAISE EXCEPTION 'V22_CONSENT_REVISION_CONFLICT' USING ERRCODE='40001';
 END IF;
 IF p_action='grant' AND p_person IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM photo.project_persons p WHERE p.tenant_id=p_tenant
   AND p.project_id=p_project AND p.id=p_person AND p.state='active') THEN
  RAISE EXCEPTION 'V22_PERSON_REVOKED' USING ERRCODE='23514';
 END IF;
 next_status:=CASE WHEN p_action='grant' THEN 'granted' ELSE 'revoked' END;
 UPDATE photo.consent_grants SET status=next_status,epoch=grant_row.epoch+1,
  policy_version=p_policy_version,actor_id=p_actor WHERE id=p_consent
 RETURNING * INTO changed;
 INSERT INTO photo.consent_events(tenant_id,project_id,consent_id,epoch,action,
  actor_id,policy_version) VALUES(p_tenant,p_project,p_consent,changed.epoch,
  p_action,p_actor,p_policy_version);
 IF p_action='revoke' THEN
  FOR dependent IN SELECT DISTINCT w.run_id FROM photo.workflow_consent_links l
   JOIN photo.v2_workflows w ON w.tenant_id=l.tenant_id AND w.id=l.workflow_id
   WHERE l.tenant_id=p_tenant AND l.project_id=p_project
    AND l.consent_id=p_consent AND l.consent_epoch=grant_row.epoch
   ORDER BY w.run_id LOOP
   SELECT * INTO run_row FROM photo.runs r WHERE r.tenant_id=p_tenant
    AND r.id=dependent.run_id FOR UPDATE;
   IF run_row.status IN('draft','queued','running','waiting_review') THEN
    IF run_row.revision>=9007199254740991 THEN
     RAISE EXCEPTION 'V22_RUN_REVISION_EXHAUSTED' USING ERRCODE='22003';
    END IF;
    UPDATE photo.runs SET cancel_requested=true,
     status=CASE WHEN status='draft' THEN 'draft' ELSE 'cancelling' END,
     revision=revision+1 WHERE tenant_id=p_tenant AND id=run_row.id;
    FOR task_row IN SELECT t.id FROM photo.tasks t WHERE t.tenant_id=p_tenant
     AND t.run_id=run_row.id AND t.state NOT IN('succeeded','failed','cancelled','skipped')
     ORDER BY t.id LOOP
     UPDATE photo.tasks SET cancel_requested=true WHERE tenant_id=p_tenant
      AND id=task_row.id;
    END LOOP;
   END IF;
  END LOOP;
 END IF;
 event_id:=gen_random_uuid();
 INSERT INTO photo.outbox(tenant_id,event_id,destination,routing_key,payload)
 VALUES(p_tenant,event_id,'photo.events.v1','v2.consent.'||p_action,
  jsonb_build_object('schema_version',1,'event_id',event_id,
   'type','v2.consent.'||p_action,'tenant_id',p_tenant,'project_id',p_project,
   'consent_id',p_consent,'epoch',changed.epoch));
 RETURN jsonb_build_object('id',changed.id,'revision',changed.revision::text,
  'epoch',changed.epoch::text,'status',changed.status);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.change_v2_consent(uuid,uuid,uuid,bigint,text,uuid,text,text,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.change_v2_consent(uuid,uuid,uuid,bigint,text,uuid,text,text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.change_v2_consent(uuid,uuid,uuid,bigint,text,uuid,text,text,uuid,uuid) TO photo_api;

-- Source: 00197_observation_mutations.sql
-- The caller must validate FaceObservations JSON and derive p_face from the
-- requested observation_id before calling this trusted transaction boundary.
-- Tenant lock precedes consent and person locks, matching revoke lock order.
-- +goose StatementBegin
CREATE FUNCTION photo.confirm_v22_observation(
 p_tenant uuid,p_project uuid,p_person uuid,p_expected bigint,
 p_version uuid,p_source uuid,p_source_sha text,p_face uuid,
 p_evidence uuid,p_evidence_sha text,p_consent uuid,p_epoch bigint,
 p_actor uuid,p_session uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE grant_row photo.consent_grants%ROWTYPE;
 person_row photo.project_persons%ROWTYPE;
 existing photo.person_observations%ROWTYPE;
 created photo.person_observations%ROWTYPE;
BEGIN
 IF p_tenant IS NULL OR p_project IS NULL OR p_person IS NULL OR p_version IS NULL
  OR p_source IS NULL OR p_face IS NULL OR p_evidence IS NULL OR p_consent IS NULL
  OR p_actor IS NULL OR p_session IS NULL OR p_expected IS NULL OR p_expected<1
  OR p_epoch IS NULL OR p_epoch<1 OR p_source_sha !~ '^[0-9a-f]{64}$'
  OR p_evidence_sha !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'V22_OBSERVATION_INVALID' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND OR NOT photo.v2_editor_authorized(p_tenant,p_project,p_actor,p_session) THEN
  RAISE EXCEPTION 'V22_OBSERVATION_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT * INTO grant_row FROM photo.consent_grants g WHERE g.tenant_id=p_tenant
  AND g.project_id=p_project AND g.id=p_consent FOR UPDATE;
 IF grant_row.id IS NULL OR grant_row.person_id IS DISTINCT FROM p_person
  OR grant_row.purpose<>'identity_matching' OR grant_row.status<>'granted'
  OR grant_row.epoch<>p_epoch THEN
  RAISE EXCEPTION 'V22_OBSERVATION_CONSENT_CONFLICT' USING ERRCODE='40001';
 END IF;
 SELECT * INTO person_row FROM photo.project_persons p WHERE p.tenant_id=p_tenant
  AND p.project_id=p_project AND p.id=p_person FOR UPDATE;
 IF person_row.id IS NULL THEN
  RAISE EXCEPTION 'V22_OBSERVATION_PERSON_NOT_FOUND' USING ERRCODE='P0002';
 END IF;
 IF person_row.state<>'active' OR person_row.revision<>p_expected
  OR person_row.revision>=9007199254740991 THEN
  RAISE EXCEPTION 'V22_OBSERVATION_REVISION_CONFLICT' USING ERRCODE='40001';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM photo.asset_versions v
   JOIN photo.assets asset ON asset.tenant_id=v.tenant_id AND asset.id=v.asset_id
   WHERE v.tenant_id=p_tenant AND v.id=p_version AND asset.project_id=p_project
    AND asset.deleted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM photo.artifacts source
   WHERE source.tenant_id=p_tenant AND source.id=p_source
    AND source.sha256=p_source_sha AND source.output_role='working_image'
    AND source.media_type='application/json' AND source.state='ready'
    AND source.object_version IS NOT NULL AND source.verified_at IS NOT NULL
    AND (source.expires_at IS NULL OR source.expires_at>clock_timestamp())) THEN
  RAISE EXCEPTION 'V22_OBSERVATION_SOURCE_INVALID' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM photo.artifacts evidence
   JOIN photo.tasks task ON task.tenant_id=evidence.tenant_id
    AND task.id=evidence.created_by_task_id
   JOIN photo.task_results result ON result.tenant_id=task.tenant_id
    AND result.task_id=task.id AND result.id=task.canonical_result_id
   JOIN photo.output_uploads upload ON upload.tenant_id=evidence.tenant_id
    AND upload.artifact_id=evidence.id AND upload.task_id=task.id
    AND upload.attempt=result.attempt AND upload.fence=result.fencing_token
   JOIN photo.runs run ON run.tenant_id=task.tenant_id AND run.id=task.run_id
   JOIN photo.v2_workflows workflow ON workflow.tenant_id=run.tenant_id
    AND workflow.run_id=run.id AND workflow.project_id=p_project
   WHERE evidence.tenant_id=p_tenant AND evidence.id=p_evidence
    AND evidence.sha256=p_evidence_sha AND evidence.output_role='faces'
    AND evidence.media_type='application/json' AND evidence.state='ready'
    AND evidence.object_version IS NOT NULL AND evidence.verified_at IS NOT NULL
    AND (evidence.expires_at IS NULL OR evidence.expires_at>clock_timestamp())
    AND task.operation='session.describe' AND task.state='succeeded'
    AND evidence.produced_attempt=result.attempt
    AND evidence.produced_fence=result.fencing_token
    AND upload.state='ready' AND upload.role='faces'
    AND upload.sha256=evidence.sha256
    AND task.inputs @> jsonb_build_array(jsonb_build_object(
     'artifact_id',p_source::text,'sha256',p_source_sha))) THEN
  RAISE EXCEPTION 'V22_OBSERVATION_EVIDENCE_INVALID' USING ERRCODE='23514';
 END IF;
 SELECT * INTO existing FROM photo.person_observations o WHERE o.tenant_id=p_tenant
  AND o.asset_version_id=p_version AND o.face_id=p_face FOR UPDATE;
 IF existing.id IS NOT NULL THEN
  IF existing.project_id<>p_project THEN
   RAISE EXCEPTION 'V22_OBSERVATION_ASSOCIATION_CONFLICT' USING ERRCODE='23505';
  END IF;
  IF existing.person_id<>p_person THEN
   IF NOT EXISTS(SELECT 1 FROM photo.project_persons old_person
    WHERE old_person.tenant_id=p_tenant AND old_person.project_id=p_project
     AND old_person.id=existing.person_id AND old_person.state='revoked') THEN
    RAISE EXCEPTION 'V22_OBSERVATION_ASSOCIATION_CONFLICT' USING ERRCODE='23505';
   END IF;
   INSERT INTO photo.audit_log(tenant_id,actor_type,actor_id,action,resource_type,
    resource_id,request_id,details)
   VALUES(p_tenant,'user',p_actor,'v2.observation.rebind','person_observation',
    existing.id,gen_random_uuid(),jsonb_build_object('project_id',p_project,
     'previous_person_id',existing.person_id,'person_id',p_person,
     'asset_version_id',p_version,'face_id',p_face,
     'previous_evidence_artifact_id',existing.evidence_artifact_id,
     'evidence_artifact_id',p_evidence,'consent_id',p_consent,'consent_epoch',p_epoch));
   UPDATE photo.person_observations SET person_id=p_person,
    evidence_artifact_id=p_evidence,confirmed_by=p_actor
    WHERE tenant_id=p_tenant AND id=existing.id RETURNING * INTO existing;
   UPDATE photo.project_persons SET updated_at=clock_timestamp()
    WHERE tenant_id=p_tenant AND id=p_person;
  END IF;
  RETURN jsonb_build_object('id',existing.id,'revision',existing.revision::text,
   'person_id',existing.person_id);
 END IF;
 INSERT INTO photo.person_observations(tenant_id,project_id,person_id,
  asset_version_id,face_id,evidence_artifact_id,confirmed_by)
 VALUES(p_tenant,p_project,p_person,p_version,p_face,p_evidence,p_actor)
 RETURNING * INTO created;
 UPDATE photo.project_persons SET updated_at=clock_timestamp()
  WHERE tenant_id=p_tenant AND id=p_person;
 INSERT INTO photo.audit_log(tenant_id,actor_type,actor_id,action,resource_type,
  resource_id,request_id,details)
 VALUES(p_tenant,'user',p_actor,'v2.observation.confirm','person_observation',
  created.id,gen_random_uuid(),jsonb_build_object('project_id',p_project,
   'person_id',p_person,'asset_version_id',p_version,'face_id',p_face,
   'evidence_artifact_id',p_evidence,'consent_id',p_consent,'consent_epoch',p_epoch));
 RETURN jsonb_build_object('id',created.id,'revision',created.revision::text,
  'person_id',created.person_id);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.confirm_v22_observation(uuid,uuid,uuid,bigint,uuid,uuid,text,uuid,uuid,text,uuid,bigint,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.confirm_v22_observation(uuid,uuid,uuid,bigint,uuid,uuid,text,uuid,uuid,text,uuid,bigint,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.confirm_v22_observation(uuid,uuid,uuid,bigint,uuid,uuid,text,uuid,uuid,text,uuid,bigint,uuid,uuid) TO photo_api;

-- Source: 00197_analysis_preflight.sql
-- Read-only preflight for the trusted V22 compiler. The draft-shell/admission
-- transaction must repeat revision, selection and qualification checks before
-- it can queue a workflow; this function alone never creates a run.
-- +goose StatementBegin
CREATE FUNCTION photo.preflight_v22_analysis(
 p_tenant uuid,p_session uuid,p_expected bigint,p_selection uuid,
 p_manual jsonb,p_actor uuid,p_auth_session uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE session_row photo.shoot_sessions%ROWTYPE;
 snapshot_row photo.snapshots%ROWTYPE;
 ref jsonb; prev_members jsonb; context_refs jsonb:='[]'::jsonb;
 seen_groups uuid[]:=ARRAY[]::uuid[]; chosen uuid; previous uuid; chosen_group uuid;
 item_count bigint;
BEGIN
 IF p_tenant IS NULL OR p_session IS NULL OR p_selection IS NULL OR
  p_actor IS NULL OR p_auth_session IS NULL OR p_expected IS NULL OR
  p_expected<1 OR jsonb_typeof(p_manual) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'V22_ANALYSIS_INVALID' USING ERRCODE='22023';
 END IF;
 IF jsonb_array_length(p_manual)>5000 THEN
  RAISE EXCEPTION 'V22_ANALYSIS_INVALID' USING ERRCODE='22023';
 END IF;
 SELECT * INTO session_row FROM photo.shoot_sessions s WHERE s.tenant_id=p_tenant
  AND s.id=p_session FOR SHARE;
 IF session_row.id IS NULL OR NOT photo.v2_editor_authorized(
  p_tenant,session_row.project_id,p_actor,p_auth_session) THEN
  RAISE EXCEPTION 'V22_ANALYSIS_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF session_row.revision<>p_expected OR session_row.state='archived' THEN
  RAISE EXCEPTION 'V22_ANALYSIS_REVISION_CONFLICT' USING ERRCODE='40001';
 END IF;
 SELECT * INTO snapshot_row FROM photo.snapshots x WHERE x.tenant_id=p_tenant
  AND x.id=p_selection AND x.kind='selection'
  AND x.collection_id=session_row.collection_id
  AND x.principal_type='user' AND x.principal_id=p_actor
  AND x.expires_at>clock_timestamp() FOR SHARE;
 IF snapshot_row.id IS NULL OR snapshot_row.item_count NOT BETWEEN 1 AND 5000 THEN
  RAISE EXCEPTION 'V22_ANALYSIS_SELECTION_INVALID' USING ERRCODE='23514';
 END IF;
 SELECT count(*) INTO item_count FROM photo.snapshot_items i
  JOIN photo.asset_versions v ON v.tenant_id=i.tenant_id
   AND v.id=i.asset_version_id AND v.master_artifact_id=i.artifact_id
   AND v.content_hash=i.sha256
  JOIN photo.assets a ON a.tenant_id=v.tenant_id AND a.id=v.asset_id
   AND a.project_id=session_row.project_id AND a.deleted_at IS NULL
   AND a.upload_state='verified'
  JOIN photo.artifacts artifact ON artifact.tenant_id=i.tenant_id
   AND artifact.id=i.artifact_id AND artifact.sha256=i.sha256
   AND artifact.state='ready' AND artifact.object_version IS NOT NULL
   AND (artifact.expires_at IS NULL OR artifact.expires_at>clock_timestamp())
  WHERE i.tenant_id=p_tenant AND i.snapshot_id=p_selection
   AND i.ordinal BETWEEN 0 AND snapshot_row.item_count-1;
 IF item_count<>snapshot_row.item_count OR EXISTS(
  SELECT 1 FROM photo.snapshot_items i WHERE i.tenant_id=p_tenant
   AND i.snapshot_id=p_selection AND (i.ordinal<0 OR
    i.ordinal>=snapshot_row.item_count)) THEN
  RAISE EXCEPTION 'V22_ANALYSIS_SELECTION_INVALID' USING ERRCODE='23514';
 END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(p_manual) LOOP
  IF jsonb_typeof(ref) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'V22_ANALYSIS_REFERENCE_INVALID' USING ERRCODE='22023';
  END IF;
  IF (ref-'previous_analysis_id'-'group_id'-'asset_version_id')<>'{}'::jsonb OR
   NOT (ref ?& ARRAY['previous_analysis_id','group_id','asset_version_id']) OR
   coalesce(ref->>'previous_analysis_id','') !~
    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR
   coalesce(ref->>'group_id','') !~
    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR
   coalesce(ref->>'asset_version_id','') !~
    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
   RAISE EXCEPTION 'V22_ANALYSIS_REFERENCE_INVALID' USING ERRCODE='22023';
  END IF;
  previous:=(ref->>'previous_analysis_id')::uuid;
  chosen_group:=(ref->>'group_id')::uuid;
  chosen:=(ref->>'asset_version_id')::uuid;
  IF chosen_group=ANY(seen_groups) OR NOT EXISTS(
   SELECT 1 FROM photo.session_analyses analysis
    JOIN photo.scene_groups scene ON scene.tenant_id=analysis.tenant_id
     AND scene.analysis_id=analysis.id
    WHERE analysis.tenant_id=p_tenant AND analysis.project_id=session_row.project_id
     AND analysis.session_id=p_session AND analysis.id=previous AND scene.id=chosen_group)
   OR NOT EXISTS(SELECT 1 FROM photo.scene_members member
    WHERE member.tenant_id=p_tenant AND member.group_id=chosen_group
     AND member.asset_version_id=chosen)
   OR NOT EXISTS(SELECT 1 FROM photo.snapshot_items selected
    WHERE selected.tenant_id=p_tenant AND selected.snapshot_id=p_selection
     AND selected.asset_version_id=chosen) THEN
   RAISE EXCEPTION 'V22_ANALYSIS_REFERENCE_CONFLICT' USING ERRCODE='23514';
  END IF;
  seen_groups:=array_append(seen_groups,chosen_group);
  SELECT jsonb_agg(member.asset_version_id ORDER BY member.snapshot_ordinal,
    member.asset_version_id) INTO prev_members FROM photo.scene_members member
   WHERE member.tenant_id=p_tenant AND member.group_id=chosen_group;
  IF prev_members IS NULL OR EXISTS(
   SELECT 1 FROM photo.scene_members member WHERE member.tenant_id=p_tenant
    AND member.group_id=chosen_group AND NOT EXISTS(
     SELECT 1 FROM photo.snapshot_items selected
      WHERE selected.tenant_id=p_tenant AND selected.snapshot_id=p_selection
       AND selected.asset_version_id=member.asset_version_id)) THEN
   RAISE EXCEPTION 'V22_ANALYSIS_REFERENCE_CONFLICT' USING ERRCODE='23514';
  END IF;
  context_refs:=context_refs || jsonb_build_array(jsonb_build_object(
   'asset_version_id',chosen,'previous_members',prev_members));
 END LOOP;
 RETURN jsonb_build_object('session_id',p_session,'project_id',session_row.project_id,
  'session_revision',session_row.revision::text,'collection_id',session_row.collection_id,
  'selection_snapshot_id',p_selection,'selection_digest',snapshot_row.digest,
  'item_count',snapshot_row.item_count::text,'manual_references',context_refs);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.preflight_v22_analysis(uuid,uuid,bigint,uuid,jsonb,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.preflight_v22_analysis(uuid,uuid,bigint,uuid,jsonb,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.preflight_v22_analysis(uuid,uuid,bigint,uuid,jsonb,uuid,uuid) TO photo_api;

-- Source: 00197_analysis_snapshot.sql
-- Freeze the validated selection before V21 draft admission. The caller must
-- use the deterministic run UUID derived from the request idempotency key.
-- The transaction aborts if the selection, session revision or ACL changes.
-- +goose StatementBegin
CREATE FUNCTION photo.freeze_v22_analysis_snapshot(
 p_tenant uuid,p_run uuid,p_session uuid,p_expected bigint,p_selection uuid,
 p_manual jsonb,p_actor uuid,p_auth_session uuid,p_input_digest text)
RETURNS TABLE(snapshot_id uuid,context jsonb)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE source photo.snapshots%ROWTYPE; frozen photo.snapshots%ROWTYPE;
 h bytea; target uuid; preflight jsonb; copied bigint;
BEGIN
 IF p_run IS NULL OR p_input_digest IS NULL OR
  p_input_digest !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'V22_ANALYSIS_RUN_INVALID' USING ERRCODE='22023';
 END IF;
 preflight:=photo.preflight_v22_analysis(p_tenant,p_session,p_expected,
  p_selection,p_manual,p_actor,p_auth_session);
 SELECT * INTO source FROM photo.snapshots s WHERE s.tenant_id=p_tenant
  AND s.id=p_selection FOR SHARE;
 h:=public.digest(uuid_send(p_run)||convert_to('analysis.snapshot','UTF8'),'sha1');
 h:=set_byte(h,6,(get_byte(h,6)&15)|80);
 h:=set_byte(h,8,(get_byte(h,8)&63)|128);
 target:=encode(substring(h FROM 1 FOR 16),'hex')::uuid;
 SELECT * INTO frozen FROM photo.snapshots s WHERE s.tenant_id=p_tenant
  AND s.id=target FOR UPDATE;
 IF frozen.id IS NOT NULL THEN
  IF frozen.kind<>'v2' OR frozen.collection_id IS DISTINCT FROM source.collection_id
   OR frozen.source_revision IS DISTINCT FROM source.source_revision
   OR frozen.principal_type<>'user' OR frozen.principal_id<>p_actor
   OR frozen.digest<>p_input_digest OR frozen.item_count<>source.item_count
   OR EXISTS(SELECT i.ordinal,i.item_id,i.asset_version_id,i.artifact_id,i.sha256,i.payload
     FROM photo.snapshot_items i WHERE i.tenant_id=p_tenant AND i.snapshot_id=p_selection
     EXCEPT SELECT i.ordinal,i.item_id,i.asset_version_id,i.artifact_id,i.sha256,i.payload
     FROM photo.snapshot_items i WHERE i.tenant_id=p_tenant AND i.snapshot_id=target)
   OR EXISTS(SELECT i.ordinal,i.item_id,i.asset_version_id,i.artifact_id,i.sha256,i.payload
     FROM photo.snapshot_items i WHERE i.tenant_id=p_tenant AND i.snapshot_id=target
     EXCEPT SELECT i.ordinal,i.item_id,i.asset_version_id,i.artifact_id,i.sha256,i.payload
     FROM photo.snapshot_items i WHERE i.tenant_id=p_tenant AND i.snapshot_id=p_selection) THEN
   RAISE EXCEPTION 'V22_ANALYSIS_SNAPSHOT_CONFLICT' USING ERRCODE='23514';
  END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM photo.runs r WHERE r.tenant_id=p_tenant AND r.id=p_run) THEN
   RAISE EXCEPTION 'V22_ANALYSIS_RUN_ALREADY_ADMITTED' USING ERRCODE='23514';
  END IF;
  INSERT INTO photo.snapshots(id,tenant_id,kind,collection_id,source_revision,
   principal_type,principal_id,digest,item_count,expires_at)
  VALUES(target,p_tenant,'v2',source.collection_id,source.source_revision,
   'user',p_actor,p_input_digest,source.item_count,
   clock_timestamp()+interval '1 hour');
  INSERT INTO photo.snapshot_items(tenant_id,snapshot_id,ordinal,item_id,
   asset_version_id,artifact_id,sha256,payload)
  SELECT p_tenant,target,i.ordinal,i.item_id,i.asset_version_id,i.artifact_id,
   i.sha256,i.payload FROM photo.snapshot_items i
  WHERE i.tenant_id=p_tenant AND i.snapshot_id=p_selection ORDER BY i.ordinal;
  GET DIAGNOSTICS copied=ROW_COUNT;
  IF copied<>source.item_count THEN
   RAISE EXCEPTION 'V22_ANALYSIS_SNAPSHOT_INCOMPLETE' USING ERRCODE='23514';
  END IF;
  UPDATE photo.snapshots SET expires_at=NULL WHERE tenant_id=p_tenant AND id=target;
 END IF;
 RETURN QUERY SELECT target,preflight || jsonb_build_object(
  'frozen_snapshot_id',target,'frozen_snapshot_digest',p_input_digest);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.freeze_v22_analysis_snapshot(uuid,uuid,uuid,bigint,uuid,jsonb,uuid,uuid,text)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.freeze_v22_analysis_snapshot(uuid,uuid,uuid,bigint,uuid,jsonb,uuid,uuid,text)
 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.freeze_v22_analysis_snapshot(uuid,uuid,uuid,bigint,uuid,jsonb,uuid,uuid,text)
 TO photo_scheduler;

-- The transient non-null expiry is a construction marker inside the freeze
-- transaction. A sealed V2 snapshot (expires_at NULL) cannot be reopened.
-- +goose StatementBegin
CREATE FUNCTION photo.v22_tenant_purge_active(p_tenant uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT EXISTS(SELECT 1 FROM photo.tenants t JOIN photo.deletion_jobs j
  ON j.tenant_id=t.id AND j.resource_type='tenant' AND j.status='running'
  WHERE t.id=p_tenant AND t.status='deleting' AND j.cleanup_token IS NOT NULL
   AND j.cleanup_lease_until>clock_timestamp())
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_tenant_purge_active(uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_tenant_purge_active(uuid) FROM PUBLIC;

-- +goose StatementBegin
CREATE FUNCTION photo.guard_v22_frozen_snapshot() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
BEGIN
 IF OLD.kind='v2' AND OLD.expires_at IS NULL THEN
  IF TG_OP='DELETE' THEN
   IF photo.v22_tenant_purge_active(OLD.tenant_id) THEN RETURN OLD; END IF;
   RAISE EXCEPTION 'V22_FROZEN_SNAPSHOT_IMMUTABLE' USING ERRCODE='23514';
  END IF;
  IF NEW.expires_at IS DISTINCT FROM OLD.expires_at THEN
   RAISE EXCEPTION 'V22_FROZEN_SNAPSHOT_IMMUTABLE' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.guard_v22_frozen_snapshot() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.guard_v22_frozen_snapshot() FROM PUBLIC;
CREATE TRIGGER v22_frozen_snapshot_guard BEFORE UPDATE OR DELETE ON photo.snapshots
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v22_frozen_snapshot();

-- +goose StatementBegin
CREATE FUNCTION photo.guard_v22_frozen_items() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE sealed boolean; target_tenant uuid; target_snapshot uuid;
BEGIN
 IF TG_OP='DELETE' THEN
  target_tenant:=OLD.tenant_id; target_snapshot:=OLD.snapshot_id;
 ELSE
  target_tenant:=NEW.tenant_id; target_snapshot:=NEW.snapshot_id;
 END IF;
 SELECT s.kind='v2' AND s.expires_at IS NULL INTO sealed FROM photo.snapshots s
  WHERE s.tenant_id=target_tenant AND s.id=target_snapshot FOR SHARE;
 IF sealed THEN
  IF TG_OP='DELETE' AND photo.v22_tenant_purge_active(target_tenant) THEN
   RETURN OLD;
  END IF;
  RAISE EXCEPTION 'V22_FROZEN_ITEMS_IMMUTABLE' USING ERRCODE='23514';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.guard_v22_frozen_items() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.guard_v22_frozen_items() FROM PUBLIC;
CREATE TRIGGER v22_frozen_items_guard BEFORE INSERT OR UPDATE OR DELETE ON photo.snapshot_items
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v22_frozen_items();

-- Source: 00197_analysis_begin.sql
-- First transaction of session admission. It creates a draft run and quota
-- reservation before any Params/InputSnapshot object publication. No task is
-- runnable until the later staged graph is registered and sealed.
-- +goose StatementBegin
CREATE FUNCTION photo.begin_v22_analysis_draft(
 p_tenant uuid,p_run uuid,p_workflow uuid,p_project uuid,p_snapshot uuid,
 p_session uuid,p_selection uuid,p_expected bigint,p_manual jsonb,
 p_actor uuid,p_auth_session uuid,p_policy_sha text,p_config_sha text,
 p_config jsonb,p_bytes bigint,p_key text,p_request_sha text)
RETURNS TABLE(outcome text,run_id uuid)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE idem photo.idempotency_records%ROWTYPE; existing photo.runs%ROWTYPE;
 frozen photo.snapshots%ROWTYPE; context jsonb; h bytea; expected_run uuid;
 expected_workflow uuid; expected_snapshot uuid; capacity numeric; used numeric;
BEGIN
 IF p_key IS NULL OR p_key COLLATE "C" !~ '^[!-~]{1,128}$'
  OR p_request_sha IS NULL OR p_request_sha !~ '^[0-9a-f]{64}$'
  OR p_policy_sha IS NULL OR p_policy_sha !~ '^[0-9a-f]{64}$'
  OR p_config_sha IS NULL OR p_config_sha !~ '^[0-9a-f]{64}$'
  OR p_bytes IS NULL OR p_bytes NOT BETWEEN 1 AND 9007199254740991
  OR jsonb_typeof(p_config) IS DISTINCT FROM 'object'
  OR p_config->>'project_id' IS DISTINCT FROM p_project::text
  OR p_config->>'session_id' IS DISTINCT FROM p_session::text
  OR jsonb_typeof(p_config->'v22_session_plan') IS DISTINCT FROM 'object'
  OR ((p_config->'v22_session_plan')-'schema_version'-'item_count'
   -'snapshot_digest'-'policy'-'context_sha')<>'{}'::jsonb
  OR p_config->'v22_session_plan'->>'schema_version' IS DISTINCT FROM '1'
  OR coalesce(p_config->'v22_session_plan'->>'item_count','') !~ '^[1-9][0-9]{0,3}$'
  OR jsonb_typeof(p_config->'v22_session_plan'->'policy') IS DISTINCT FROM 'object'
  OR coalesce(p_config->'v22_session_plan'->>'context_sha','') !~ '^[0-9a-f]{64}$'
  OR coalesce(p_config->'v22_session_plan'->>'snapshot_digest','') !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'V22_ANALYSIS_DRAFT_INVALID' USING ERRCODE='22023';
 END IF;
 h:=public.digest(uuid_send(p_tenant)||convert_to(
  'V2.Admit:'||p_actor::text||':'||p_key,'UTF8'),'sha1');
 h:=set_byte(h,6,(get_byte(h,6)&15)|80);
 h:=set_byte(h,8,(get_byte(h,8)&63)|128);
 expected_run:=encode(substring(h FROM 1 FOR 16),'hex')::uuid;
 h:=public.digest(uuid_send(expected_run)||convert_to('workflow','UTF8'),'sha1');
 h:=set_byte(h,6,(get_byte(h,6)&15)|80);
 h:=set_byte(h,8,(get_byte(h,8)&63)|128);
 expected_workflow:=encode(substring(h FROM 1 FOR 16),'hex')::uuid;
 h:=public.digest(uuid_send(expected_run)||convert_to('analysis.snapshot','UTF8'),'sha1');
 h:=set_byte(h,6,(get_byte(h,6)&15)|80);
 h:=set_byte(h,8,(get_byte(h,8)&63)|128);
 expected_snapshot:=encode(substring(h FROM 1 FOR 16),'hex')::uuid;
 IF p_run IS DISTINCT FROM expected_run OR
  p_workflow IS DISTINCT FROM expected_workflow OR
  p_snapshot IS DISTINCT FROM expected_snapshot THEN
  RAISE EXCEPTION 'V22_ANALYSIS_ID_INVALID' USING ERRCODE='22023';
 END IF;
 IF NOT photo.v2_editor_authorized(p_tenant,p_project,p_actor,p_auth_session)
  OR NOT EXISTS(SELECT 1 FROM photo.shoot_sessions x WHERE x.tenant_id=p_tenant
   AND x.id=p_session AND x.project_id=p_project) THEN
  RAISE EXCEPTION 'V22_ANALYSIS_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 INSERT INTO photo.idempotency_records(tenant_id,principal_type,principal_id,
  route,key,request_hash,expires_at)
 VALUES(p_tenant,'user',p_actor,'V2.Admit',p_key,p_request_sha,
  clock_timestamp()+interval '24 hours')
 ON CONFLICT(tenant_id,principal_type,principal_id,route,key) DO NOTHING;
 SELECT * INTO idem FROM photo.idempotency_records i WHERE i.tenant_id=p_tenant
  AND i.principal_type='user' AND i.principal_id=p_actor
  AND i.route='V2.Admit' AND i.key=p_key FOR UPDATE;
 IF idem.request_hash<>p_request_sha THEN
  RETURN QUERY SELECT 'conflict'::text,NULL::uuid; RETURN;
 END IF;
 IF idem.resource_id IS NOT NULL THEN
  SELECT * INTO existing FROM photo.runs r WHERE r.tenant_id=p_tenant
   AND r.id=idem.resource_id AND r.created_by=p_actor AND r.kind='v2';
  IF existing.id IS NULL OR existing.id<>p_run THEN
   RAISE EXCEPTION 'V22_ANALYSIS_IDEMPOTENCY_CORRUPT' USING ERRCODE='23514';
  END IF;
  IF idem.response_status=202 AND existing.graph_sealed THEN
   RETURN QUERY SELECT 'replayed'::text,existing.id; RETURN;
  END IF;
  IF idem.response_status IS NULL AND existing.status='draft'
   AND NOT existing.graph_sealed AND existing.input_snapshot_id=p_snapshot
   AND existing.config_hash=p_config_sha AND existing.config_snapshot=p_config
   AND EXISTS(SELECT 1 FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant
    AND w.run_id=p_run AND w.id=p_workflow AND w.project_id=p_project
    AND w.workflow_type='session' AND w.policy_sha=p_policy_sha)
   AND EXISTS(SELECT 1 FROM photo.quota_reservations q WHERE q.tenant_id=p_tenant
    AND q.holder_type='run' AND q.holder_id=p_run AND q.state='reserved'
    AND q.bytes=p_bytes AND q.expires_at>clock_timestamp()) THEN
   RETURN QUERY SELECT 'pending'::text,existing.id; RETURN;
  END IF;
  RETURN QUERY SELECT 'expired'::text,existing.id; RETURN;
 END IF;
 context:=photo.preflight_v22_analysis(p_tenant,p_session,p_expected,
  p_selection,p_manual,p_actor,p_auth_session);
 IF context->>'project_id' IS DISTINCT FROM p_project::text THEN
  RAISE EXCEPTION 'V22_ANALYSIS_PROJECT_INVALID' USING ERRCODE='23514';
 END IF;
 SELECT * INTO frozen FROM photo.snapshots s WHERE s.tenant_id=p_tenant
  AND s.id=p_snapshot AND s.kind='v2' AND s.collection_id=(context->>'collection_id')::uuid
  AND s.principal_type='user' AND s.principal_id=p_actor
  AND s.item_count=(context->>'item_count')::bigint
  AND s.item_count=(p_config->'v22_session_plan'->>'item_count')::bigint
  AND s.digest=p_config->'v22_session_plan'->>'snapshot_digest'
  AND s.expires_at IS NULL FOR SHARE;
 IF frozen.id IS NULL THEN
  RAISE EXCEPTION 'V22_ANALYSIS_FROZEN_SNAPSHOT_INVALID' USING ERRCODE='23514';
 END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 SELECT (t.quotas->>'storage_bytes')::numeric INTO capacity FROM photo.tenants t
  WHERE t.id=p_tenant AND t.status='active' FOR UPDATE;
 SELECT u.storage_bytes::numeric+u.reserved_bytes INTO used FROM photo.tenant_usage u
  WHERE u.tenant_id=p_tenant;
 IF capacity IS NULL OR used IS NULL OR used+p_bytes>capacity OR
  used+p_bytes>9007199254740991 THEN
  RAISE EXCEPTION 'V22_ANALYSIS_QUOTA' USING ERRCODE='23514';
 END IF;
 INSERT INTO photo.runs(id,tenant_id,kind,status,input_snapshot_id,
  config_snapshot,config_hash,created_by,failure_policy,graph_sealed)
 VALUES(p_run,p_tenant,'v2','draft',p_snapshot,p_config,p_config_sha,
  p_actor,'fail_fast',false);
 INSERT INTO photo.v2_workflows(id,tenant_id,project_id,run_id,
  input_snapshot_id,workflow_type,renderer_version,policy_sha)
 VALUES(p_workflow,p_tenant,p_project,p_run,p_snapshot,'session','v2.2',p_policy_sha);
 INSERT INTO photo.quota_reservations(tenant_id,principal_type,principal_id,
  holder_type,holder_id,bytes,files,expires_at)
 VALUES(p_tenant,'user',p_actor,'run',p_run,p_bytes,0,
  clock_timestamp()+interval '1 hour');
 UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes+p_bytes
  WHERE tenant_id=p_tenant;
 UPDATE photo.idempotency_records SET resource_id=p_run WHERE id=idem.id;
 RETURN QUERY SELECT 'created'::text,p_run;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.begin_v22_analysis_draft(uuid,uuid,uuid,uuid,uuid,uuid,uuid,bigint,jsonb,uuid,uuid,text,text,jsonb,bigint,text,text)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.begin_v22_analysis_draft(uuid,uuid,uuid,uuid,uuid,uuid,uuid,bigint,jsonb,uuid,uuid,text,text,jsonb,bigint,text,text)
 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.begin_v22_analysis_draft(uuid,uuid,uuid,uuid,uuid,uuid,uuid,bigint,jsonb,uuid,uuid,text,text,jsonb,bigint,text,text)
 TO photo_scheduler;

-- Source: 00197_analysis_recovery.sql
-- Persist exact compiler inputs with the pending idempotency record in the
-- same transaction that creates the draft. Seal replaces this body with 202.
-- +goose StatementBegin
CREATE FUNCTION photo.save_v22_analysis_recovery(p_tenant uuid,p_actor uuid,
 p_auth_session uuid,p_run uuid,p_key text,p_request_sha text,p_body jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE idem photo.idempotency_records%ROWTYPE; r photo.runs%ROWTYPE;
 workflow photo.v2_workflows%ROWTYPE; q photo.quota_reservations%ROWTYPE;
BEGIN
 IF p_body IS NULL OR jsonb_typeof(p_body)<>'object' OR
  (p_body-'schema_version'-'snapshot'-'context'-'context_sha'-'policy_sha'-
   'model_lock_sha'-'reserved_bytes')<>'{}'::jsonb OR
  p_body->>'schema_version'<>'1' OR
  octet_length(p_body::text)>10485760 OR
  coalesce(p_body->>'context_sha','') !~ '^[0-9a-f]{64}$' OR
  coalesce(p_body->>'policy_sha','') !~ '^[0-9a-f]{64}$' OR
  coalesce(p_body->>'model_lock_sha','') !~ '^[0-9a-f]{64}$' OR
  jsonb_typeof(p_body->'snapshot')<>'object' OR
  jsonb_typeof(p_body->'context')<>'object' THEN
  RAISE EXCEPTION 'V22_RECOVERY_INVALID' USING ERRCODE='22023';
 END IF;
 SELECT * INTO idem FROM photo.idempotency_records i WHERE i.tenant_id=p_tenant
  AND i.principal_type='user' AND i.principal_id=p_actor AND i.route='V2.Admit'
  AND i.key=p_key AND i.request_hash=p_request_sha FOR UPDATE;
 SELECT * INTO r FROM photo.runs x WHERE x.tenant_id=p_tenant AND x.id=p_run
  AND x.id=idem.resource_id AND x.created_by=p_actor AND x.kind='v2';
 SELECT * INTO workflow FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant
  AND w.run_id=p_run AND w.workflow_type='session';
 SELECT * INTO q FROM photo.quota_reservations x WHERE x.tenant_id=p_tenant
  AND x.holder_type='run' AND x.holder_id=p_run AND x.state='reserved';
 IF idem.id IS NULL OR r.id IS NULL OR workflow.id IS NULL OR q.id IS NULL OR
  idem.response_status IS NOT NULL OR r.status<>'draft' OR r.graph_sealed OR
  NOT photo.v2_editor_authorized(p_tenant,workflow.project_id,p_actor,p_auth_session) OR
  r.config_snapshot->'v22_session_plan'->>'snapshot_digest' IS DISTINCT FROM
   p_body->'snapshot'->>'snapshot_digest' OR
  r.config_snapshot->'v22_session_plan'->>'context_sha' IS DISTINCT FROM
   p_body->>'context_sha' OR
  workflow.policy_sha IS DISTINCT FROM p_body->>'policy_sha' OR
  q.bytes::text IS DISTINCT FROM p_body->>'reserved_bytes' THEN
  RAISE EXCEPTION 'V22_RECOVERY_CONFLICT' USING ERRCODE='23514';
 END IF;
 IF idem.response_body IS NOT NULL AND idem.response_body<>p_body THEN
  RAISE EXCEPTION 'V22_RECOVERY_CONFLICT' USING ERRCODE='23514';
 END IF;
 UPDATE photo.idempotency_records SET response_body=p_body WHERE id=idem.id
  AND response_body IS NULL;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.save_v22_analysis_recovery(uuid,uuid,uuid,uuid,text,text,jsonb)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.save_v22_analysis_recovery(uuid,uuid,uuid,uuid,text,text,jsonb)
 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.save_v22_analysis_recovery(uuid,uuid,uuid,uuid,text,text,jsonb)
 TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.read_v22_analysis_recovery(p_tenant uuid,p_actor uuid,
 p_auth_session uuid,p_run uuid,p_key text,p_request_sha text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE idem photo.idempotency_records%ROWTYPE; r photo.runs%ROWTYPE;
 workflow photo.v2_workflows%ROWTYPE; q photo.quota_reservations%ROWTYPE;
BEGIN
 SELECT * INTO idem FROM photo.idempotency_records i WHERE i.tenant_id=p_tenant
  AND i.principal_type='user' AND i.principal_id=p_actor AND i.route='V2.Admit'
  AND i.key=p_key AND i.request_hash=p_request_sha;
 SELECT * INTO r FROM photo.runs x WHERE x.tenant_id=p_tenant AND x.id=p_run
  AND x.id=idem.resource_id AND x.created_by=p_actor AND x.kind='v2';
 SELECT * INTO workflow FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant
  AND w.run_id=p_run AND w.workflow_type='session';
 SELECT * INTO q FROM photo.quota_reservations x WHERE x.tenant_id=p_tenant
  AND x.holder_type='run' AND x.holder_id=p_run AND x.state='reserved'
  AND x.expires_at>clock_timestamp();
 IF idem.id IS NULL OR r.id IS NULL OR workflow.id IS NULL OR q.id IS NULL OR
  idem.response_status IS NOT NULL OR r.status<>'draft' OR r.graph_sealed OR
  idem.response_body IS NULL OR
  NOT photo.v2_editor_authorized(p_tenant,workflow.project_id,p_actor,p_auth_session) OR
  r.config_snapshot->'v22_session_plan'->>'snapshot_digest' IS DISTINCT FROM
   idem.response_body->'snapshot'->>'snapshot_digest' OR
  r.config_snapshot->'v22_session_plan'->>'context_sha' IS DISTINCT FROM
   idem.response_body->>'context_sha' OR
  workflow.policy_sha IS DISTINCT FROM idem.response_body->>'policy_sha' OR
  q.bytes::text IS DISTINCT FROM idem.response_body->>'reserved_bytes' THEN
  RETURN NULL;
 END IF;
 RETURN idem.response_body;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.read_v22_analysis_recovery(uuid,uuid,uuid,uuid,text,text)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.read_v22_analysis_recovery(uuid,uuid,uuid,uuid,text,text)
 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.read_v22_analysis_recovery(uuid,uuid,uuid,uuid,text,text)
 TO photo_scheduler;

-- Source: 00197_analysis_replay.sql
-- A sealed analysis can be replayed from its original idempotency ticket
-- without reopening an expired selection snapshot or current draft recipes.
-- Pending drafts still pass through the full freeze/admission checks.
-- +goose StatementBegin
CREATE FUNCTION photo.v22_analysis_replay(p_tenant uuid,p_actor uuid,p_auth_session uuid,
 p_run uuid,p_key text,p_request_sha text)
RETURNS TABLE(outcome text,run_id uuid,workflow_id uuid)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE idem photo.idempotency_records%ROWTYPE; r photo.runs%ROWTYPE;
 workflow photo.v2_workflows%ROWTYPE;
BEGIN
 IF p_tenant IS NULL OR p_actor IS NULL OR p_auth_session IS NULL OR p_run IS NULL OR
  p_key IS NULL OR p_key COLLATE "C" !~ '^[!-~]{1,128}$' OR
  p_request_sha IS NULL OR p_request_sha !~ '^[0-9a-f]{64}$' THEN
  RETURN QUERY SELECT 'invalid'::text,NULL::uuid,NULL::uuid; RETURN;
 END IF;
 SELECT * INTO idem FROM photo.idempotency_records i
  WHERE i.tenant_id=p_tenant AND i.principal_type='user'
   AND i.principal_id=p_actor AND i.route='V2.Admit' AND i.key=p_key;
 IF idem.id IS NULL THEN
  RETURN QUERY SELECT 'missing'::text,NULL::uuid,NULL::uuid; RETURN;
 END IF;
 IF idem.request_hash<>p_request_sha THEN
  RETURN QUERY SELECT 'conflict'::text,NULL::uuid,NULL::uuid; RETURN;
 END IF;
 IF idem.resource_id IS NULL THEN
  RETURN QUERY SELECT 'missing'::text,NULL::uuid,NULL::uuid; RETURN;
 END IF;
 SELECT * INTO r FROM photo.runs x WHERE x.tenant_id=p_tenant
  AND x.id=idem.resource_id AND x.id=p_run AND x.created_by=p_actor
  AND x.kind='v2';
 SELECT * INTO workflow FROM photo.v2_workflows w
  WHERE w.tenant_id=p_tenant AND w.run_id=r.id
   AND w.workflow_type='session' AND w.renderer_version='v2.2';
 IF r.id IS NULL OR workflow.id IS NULL THEN
  RETURN QUERY SELECT 'expired'::text,NULL::uuid,NULL::uuid; RETURN;
 END IF;
 IF NOT photo.v2_editor_authorized(p_tenant,workflow.project_id,
  p_actor,p_auth_session) OR NOT EXISTS(
   SELECT 1 FROM photo.shoot_sessions s WHERE s.tenant_id=p_tenant
    AND s.id::text=r.config_snapshot->>'session_id'
    AND s.project_id=workflow.project_id) THEN
  RAISE EXCEPTION 'V22_ANALYSIS_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF idem.response_status=202 AND r.graph_sealed AND
  idem.response_body->>'run_id'=r.id::text AND
  idem.response_body->>'workflow_id'=workflow.id::text AND
  idem.response_body->>'state'='queued' THEN
  RETURN QUERY SELECT 'replayed'::text,r.id,workflow.id; RETURN;
 END IF;
 IF idem.response_status IS NULL AND r.status='draft' AND
  NOT r.graph_sealed AND NOT r.cancel_requested THEN
  RETURN QUERY SELECT 'pending'::text,r.id,workflow.id; RETURN;
 END IF;
 RETURN QUERY SELECT 'expired'::text,NULL::uuid,NULL::uuid;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_analysis_replay(uuid,uuid,uuid,uuid,text,text)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_analysis_replay(uuid,uuid,uuid,uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v22_analysis_replay(uuid,uuid,uuid,uuid,text,text)
 TO photo_scheduler;

-- Source: 00197_analysis_documents.sql
-- Initial V22 documents belong to a live admission draft. A document's
-- immutable owner is either the run or the deterministic describe task ID.
ALTER TABLE photo.backend_documents DROP CONSTRAINT backend_documents_purpose_check;
ALTER TABLE photo.backend_documents ADD CONSTRAINT backend_documents_purpose_check
 CHECK (purpose IN ('task_params','review_selection','v2_input_manifest',
  'v2_session_plan_params','v2_analysis_input_snapshot','v2_analysis_context',
  'v2_analysis_consents') OR
  CASE WHEN purpose ~ '^v2_input_chunk_([0-9]|[1-9][0-9]{1,3})$'
   THEN substring(purpose from 16)::integer BETWEEN 0 AND 1953 ELSE false END OR
  CASE WHEN purpose ~ '^v2_analysis_describe_params_([0-9]|[1-3][0-9])$'
   THEN true ELSE false END);
ALTER TABLE photo.backend_documents DROP CONSTRAINT backend_documents_bytes_check;
ALTER TABLE photo.backend_documents ADD CONSTRAINT backend_documents_bytes_check
 CHECK (bytes BETWEEN 2 AND CASE WHEN purpose IN
  ('v2_analysis_input_snapshot','v2_analysis_consents') THEN 8388608 ELSE 1048576 END);

-- +goose StatementBegin
CREATE FUNCTION photo.v22_analysis_document_scope(p_tenant uuid,p_run uuid,
 p_owner uuid,p_purpose text,p_sha text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE; q photo.quota_reservations%ROWTYPE;
 ordinal integer; h bytea; expected uuid; workflow uuid;
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL OR p_owner IS NULL OR p_purpose IS NULL
  OR p_sha IS NULL OR p_sha !~ '^[0-9a-f]{64}$' THEN RETURN false; END IF;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run;
 SELECT * INTO q FROM photo.quota_reservations WHERE tenant_id=p_tenant
  AND holder_type='run' AND holder_id=p_run;
 IF r.id IS NULL OR r.kind<>'v2' OR r.status<>'draft' OR r.graph_sealed
  OR r.cancel_requested OR q.state IS DISTINCT FROM 'reserved'
  OR q.expires_at<=clock_timestamp()
  OR NOT EXISTS(SELECT 1 FROM photo.v2_workflows w
   JOIN photo.tenants t ON t.id=w.tenant_id
   WHERE w.tenant_id=p_tenant AND w.run_id=p_run
    AND w.workflow_type='session' AND w.renderer_version='v2.2'
    AND t.status='active') THEN RETURN false; END IF;
 IF p_purpose IN ('v2_analysis_input_snapshot','v2_analysis_context',
  'v2_analysis_consents') THEN
  RETURN p_owner=p_run AND CASE p_purpose
   WHEN 'v2_analysis_input_snapshot' THEN true
   WHEN 'v2_analysis_context' THEN
    p_sha=r.config_snapshot->'v22_session_plan'->>'context_sha'
   ELSE true END;
 END IF;
 IF p_purpose !~ '^v2_analysis_describe_params_([0-9]|[1-3][0-9])$'
  THEN RETURN false; END IF;
 ordinal:=substring(p_purpose from 29)::integer;
 IF ordinal >= (r.config_snapshot->'v22_session_plan'->>'item_count')::integer
  OR ordinal >= 40 THEN RETURN false; END IF;
 SELECT w.id INTO workflow FROM photo.v2_workflows w
  WHERE w.tenant_id=p_tenant AND w.run_id=p_run;
 h:=public.digest(uuid_send(workflow)||convert_to('session.describe:'||ordinal,'UTF8'),'sha1');
 h:=set_byte(h,6,(get_byte(h,6)&15)|80);
 h:=set_byte(h,8,(get_byte(h,8)&63)|128);
 expected:=encode(substring(h FROM 1 FOR 16),'hex')::uuid;
 RETURN p_owner=expected;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_analysis_document_scope(uuid,uuid,uuid,text,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_analysis_document_scope(uuid,uuid,uuid,text,text) FROM PUBLIC;

-- +goose StatementBegin
CREATE FUNCTION photo.reserve_v22_analysis_document(p_tenant uuid,p_run uuid,
 p_owner uuid,p_purpose text,p_sha text,p_bytes bigint,p_bucket text)
RETURNS TABLE(outcome text,artifact_id uuid,token uuid,ready boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE d photo.backend_documents%ROWTYPE; capacity numeric; used numeric;
 aid uuid:=gen_random_uuid(); fence uuid:=gen_random_uuid();
BEGIN
 IF p_sha IS NULL OR p_sha !~ '^[0-9a-f]{64}$' OR p_bytes IS NULL
  OR p_bytes NOT BETWEEN 2 AND (CASE WHEN p_purpose IN
   ('v2_analysis_input_snapshot','v2_analysis_consents') THEN 8388608 ELSE 1048576 END)
  OR p_bucket IS NULL OR length(p_bucket) NOT BETWEEN 3 AND 63 THEN
  RAISE EXCEPTION 'INVALID_V22_ANALYSIS_DOCUMENT' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 PERFORM id FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 IF NOT photo.v22_analysis_document_scope(p_tenant,p_run,p_owner,p_purpose,p_sha)
  THEN RETURN QUERY SELECT 'forbidden',NULL::uuid,NULL::uuid,false; RETURN; END IF;
 SELECT * INTO d FROM photo.backend_documents b WHERE b.tenant_id=p_tenant
  AND b.run_id=p_run AND b.owner_id=p_owner AND b.purpose=p_purpose FOR UPDATE;
 IF FOUND THEN
  IF d.sha256<>p_sha OR d.bytes<>p_bytes OR d.bucket<>p_bucket THEN
   RETURN QUERY SELECT 'conflict',NULL::uuid,NULL::uuid,false; RETURN; END IF;
  IF d.state='ready' THEN
   IF NOT EXISTS(SELECT 1 FROM photo.artifacts a WHERE a.tenant_id=p_tenant
    AND a.id=d.artifact_id AND a.state='ready' AND a.sha256=d.sha256
    AND a.object_version=d.object_version) THEN
    RETURN QUERY SELECT 'stale',NULL::uuid,NULL::uuid,false; RETURN; END IF;
   RETURN QUERY SELECT 'replayed',d.artifact_id,d.token,true; RETURN;
  END IF;
  IF d.state<>'pending' THEN
   RETURN QUERY SELECT 'stale',NULL::uuid,NULL::uuid,false; RETURN; END IF;
  UPDATE photo.backend_documents SET token=fence WHERE id=d.id;
  RETURN QUERY SELECT 'resumed',d.artifact_id,fence,false; RETURN;
 END IF;
 SELECT (quotas->>'storage_bytes')::numeric INTO capacity FROM photo.tenants WHERE id=p_tenant;
 SELECT storage_bytes::numeric+reserved_bytes INTO used FROM photo.tenant_usage WHERE tenant_id=p_tenant;
 IF capacity IS NULL OR used IS NULL OR used+p_bytes>capacity
  OR used+p_bytes>9007199254740991 THEN
  RETURN QUERY SELECT 'quota',NULL::uuid,NULL::uuid,false; RETURN; END IF;
 INSERT INTO photo.backend_documents(tenant_id,run_id,owner_id,purpose,
  artifact_id,token,sha256,bytes,bucket)
 VALUES(p_tenant,p_run,p_owner,p_purpose,aid,fence,p_sha,p_bytes,p_bucket);
 UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes+p_bytes WHERE tenant_id=p_tenant;
 RETURN QUERY SELECT 'created',aid,fence,false;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.reserve_v22_analysis_document(uuid,uuid,uuid,text,text,bigint,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.reserve_v22_analysis_document(uuid,uuid,uuid,text,text,bigint,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.reserve_v22_analysis_document(uuid,uuid,uuid,text,text,bigint,text) TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.complete_v22_analysis_document(p_tenant uuid,p_run uuid,
 p_owner uuid,p_purpose text,p_artifact uuid,p_token uuid,p_sha text,p_bytes bigint,
 p_bucket text,p_version text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE d photo.backend_documents%ROWTYPE; target text;
BEGIN
 IF p_token IS NULL OR p_version IS NULL OR p_version IN ('','null')
  OR length(p_version)>1024 THEN RETURN false; END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 PERFORM id FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 IF NOT photo.v22_analysis_document_scope(p_tenant,p_run,p_owner,p_purpose,p_sha)
  THEN RETURN false; END IF;
 SELECT * INTO d FROM photo.backend_documents b WHERE b.tenant_id=p_tenant
  AND b.run_id=p_run AND b.owner_id=p_owner AND b.purpose=p_purpose FOR UPDATE;
 IF d.id IS NULL OR d.artifact_id IS DISTINCT FROM p_artifact OR
  d.token IS DISTINCT FROM p_token OR d.sha256 IS DISTINCT FROM p_sha OR
  d.bytes IS DISTINCT FROM p_bytes OR d.bucket IS DISTINCT FROM p_bucket
  THEN RETURN false; END IF;
 IF d.state='ready' THEN
  RETURN d.object_version=p_version AND EXISTS(SELECT 1 FROM photo.artifacts a
   WHERE a.tenant_id=p_tenant AND a.id=p_artifact AND a.state='ready'
    AND a.sha256=d.sha256 AND a.object_version=p_version); END IF;
 IF d.state<>'pending' THEN RETURN false; END IF;
 target:='tenants/'||p_tenant||'/runs/'||p_run||'/documents/'||p_artifact;
 INSERT INTO photo.artifacts(id,tenant_id,bucket,object_key,object_version,sha256,
  bytes,media_type,state,verified_at,output_role)
 VALUES(p_artifact,p_tenant,p_bucket,target,p_version,p_sha,p_bytes,
  'application/json','ready',clock_timestamp(),p_purpose);
 UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes-d.bytes,
  storage_bytes=storage_bytes+d.bytes WHERE tenant_id=p_tenant AND reserved_bytes>=d.bytes;
 IF NOT FOUND THEN RAISE EXCEPTION 'DOCUMENT_QUOTA_ACCOUNTING' USING ERRCODE='23514'; END IF;
 UPDATE photo.backend_documents SET state='ready',object_version=p_version,
  completed_at=clock_timestamp() WHERE id=d.id;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.complete_v22_analysis_document(uuid,uuid,uuid,text,uuid,uuid,text,bigint,text,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.complete_v22_analysis_document(uuid,uuid,uuid,text,uuid,uuid,text,bigint,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.complete_v22_analysis_document(uuid,uuid,uuid,text,uuid,uuid,text,bigint,text,text) TO photo_scheduler;

-- Source: 00197_analysis_stage.sql
-- Materialize only initial describe shards. Transport closure publication and
-- seal occur later; all tasks remain blocked throughout this transaction.
-- +goose StatementBegin
CREATE FUNCTION photo.stage_v22_analysis_describes(p_tenant uuid,p_run uuid,p_tasks jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE; w photo.v2_workflows%ROWTYPE;
 item jsonb; ordinal integer:=0; expected_count integer; expected_id uuid;
 h bytea; params photo.backend_documents%ROWTYPE; existing photo.tasks%ROWTYPE;
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL OR jsonb_typeof(p_tasks) IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_tasks) NOT BETWEEN 1 AND 40
  OR pg_column_size(p_tasks)>262144 THEN RETURN false; END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 SELECT * INTO w FROM photo.v2_workflows WHERE tenant_id=p_tenant AND run_id=p_run;
 IF r.id IS NULL OR w.id IS NULL OR r.kind<>'v2' OR r.status<>'draft'
  OR r.cancel_requested OR r.graph_sealed OR w.workflow_type<>'session'
  OR w.renderer_version<>'v2.2' OR w.input_snapshot_id IS DISTINCT FROM r.input_snapshot_id
  OR (r.config_snapshot->>'project_id')::uuid IS DISTINCT FROM w.project_id
  OR NOT EXISTS(SELECT 1 FROM photo.quota_reservations q
   WHERE q.tenant_id=p_tenant AND q.holder_type='run' AND q.holder_id=p_run
    AND q.state='reserved' AND q.expires_at>clock_timestamp())
  OR NOT EXISTS(SELECT 1 FROM photo.snapshots s
   WHERE s.tenant_id=p_tenant AND s.id=r.input_snapshot_id AND s.kind='v2'
    AND s.principal_type='user' AND s.principal_id=r.created_by
    AND s.item_count=(r.config_snapshot->'v22_session_plan'->>'item_count')::integer
    AND s.digest=r.config_snapshot->'v22_session_plan'->>'snapshot_digest')
  OR NOT EXISTS(SELECT 1 FROM photo.tenants t WHERE t.id=p_tenant AND t.status='active')
  THEN RETURN false; END IF;
 expected_count:=((r.config_snapshot->'v22_session_plan'->>'item_count')::integer+127)/128;
 IF jsonb_array_length(p_tasks)<>expected_count THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM photo.backend_documents d JOIN photo.artifacts a
  ON a.tenant_id=d.tenant_id AND a.id=d.artifact_id
  WHERE d.tenant_id=p_tenant AND d.run_id=p_run AND d.owner_id=p_run
   AND d.purpose='v2_analysis_input_snapshot' AND d.state='ready'
   AND a.sha256=d.sha256 AND a.state='ready' AND a.object_version=d.object_version)
  OR NOT EXISTS(SELECT 1 FROM photo.backend_documents d JOIN photo.artifacts a
  ON a.tenant_id=d.tenant_id AND a.id=d.artifact_id
  WHERE d.tenant_id=p_tenant AND d.run_id=p_run AND d.owner_id=p_run
   AND d.purpose='v2_analysis_context' AND d.state='ready'
   AND d.sha256=r.config_snapshot->'v22_session_plan'->>'context_sha'
   AND a.sha256=d.sha256 AND a.state='ready' AND a.object_version=d.object_version)
  OR NOT EXISTS(SELECT 1 FROM photo.backend_documents d JOIN photo.artifacts a
  ON a.tenant_id=d.tenant_id AND a.id=d.artifact_id
  WHERE d.tenant_id=p_tenant AND d.run_id=p_run AND d.owner_id=p_run
   AND d.purpose='v2_analysis_consents' AND d.state='ready'
   AND a.sha256=d.sha256 AND a.state='ready' AND a.object_version=d.object_version)
  THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant
  AND t.run_id=p_run AND t.operation<>'session.describe')
  OR EXISTS(SELECT 1 FROM photo.task_edges e WHERE e.tenant_id=p_tenant
   AND e.run_id=p_run) THEN RETURN false; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_tasks) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object'
   OR (item-'id'-'node_key'-'params_artifact_id'-'params_sha'
    -'input_digest'-'execution_profile')<>'{}'::jsonb
   OR item->>'node_key' IS DISTINCT FROM 'session.describe:'||ordinal
   OR coalesce(item->>'id','') !~
    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR coalesce(item->>'params_artifact_id','') !~
    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR coalesce(item->>'params_sha','') !~ '^[0-9a-f]{64}$'
   OR coalesce(item->>'input_digest','') !~ '^[0-9a-f]{64}$'
   OR jsonb_typeof(item->'execution_profile') IS DISTINCT FROM 'object'
   OR item->'execution_profile' ? 'v2_input_manifest'
   OR coalesce(item->'execution_profile'->>'backend','') NOT IN ('cuda','cpu','mps')
   OR item->'execution_profile'->>'renderer_version' IS DISTINCT FROM 'v2.2'
   OR jsonb_typeof(item->'execution_profile'->'resource_estimate') IS DISTINCT FROM 'object'
   OR ((item->'execution_profile'->'resource_estimate')-'ram_bytes'-'vram_bytes'
    -'scratch_bytes'-'output_bytes'-'pixel_count')<>'{}'::jsonb
   OR NOT (item->'execution_profile'->'resource_estimate' ?&
    ARRAY['ram_bytes','vram_bytes','scratch_bytes','output_bytes','pixel_count'])
   OR EXISTS(SELECT 1 FROM jsonb_each(item->'execution_profile'->'resource_estimate') x
    WHERE jsonb_typeof(x.value)<>'number' OR x.value::text !~ '^(0|[1-9][0-9]{0,15})$')
   OR (item->'execution_profile'->'resource_estimate'->>'ram_bytes')::bigint<536870912
   OR (item->'execution_profile'->'resource_estimate'->>'output_bytes')::bigint<1
   OR (item->'execution_profile'->'resource_estimate'->>'scratch_bytes')::bigint<1
   OR (item->'execution_profile'->>'backend'='cuda' AND
    (item->'execution_profile'->'resource_estimate'->>'vram_bytes')::bigint<1073741824)
   OR NOT EXISTS(SELECT 1 FROM photo.operation_registry op
    WHERE op.operation='session.describe' AND op.version='1'
     AND op.resource_class='gpu'
     AND op.backends ? (item->'execution_profile'->>'backend'))
   THEN RETURN false; END IF;
  h:=public.digest(uuid_send(w.id)||convert_to('session.describe:'||ordinal,'UTF8'),'sha1');
  h:=set_byte(h,6,(get_byte(h,6)&15)|80);
  h:=set_byte(h,8,(get_byte(h,8)&63)|128);
  expected_id:=encode(substring(h FROM 1 FOR 16),'hex')::uuid;
  IF (item->>'id')::uuid<>expected_id THEN RETURN false; END IF;
  SELECT * INTO params FROM photo.backend_documents d
   WHERE d.tenant_id=p_tenant AND d.run_id=p_run AND d.owner_id=expected_id
    AND d.purpose='v2_analysis_describe_params_'||ordinal;
  IF params.id IS NULL OR params.state<>'ready'
   OR params.artifact_id IS DISTINCT FROM (item->>'params_artifact_id')::uuid
   OR params.sha256 IS DISTINCT FROM item->>'params_sha'
   OR NOT EXISTS(SELECT 1 FROM photo.artifacts a WHERE a.tenant_id=p_tenant
    AND a.id=params.artifact_id AND a.sha256=params.sha256 AND a.state='ready'
    AND a.object_version=params.object_version) THEN RETURN false; END IF;
  SELECT * INTO existing FROM photo.tasks t WHERE t.tenant_id=p_tenant
   AND t.run_id=p_run AND t.id=expected_id;
  IF existing.id IS NOT NULL THEN
   IF existing.node_key IS DISTINCT FROM item->>'node_key'
    OR existing.operation<>'session.describe' OR existing.operation_version<>'1'
    OR existing.resource_class<>'gpu' OR existing.state<>'blocked'
    OR existing.attempt<>0 OR existing.cancel_requested
    OR existing.params_artifact_id IS DISTINCT FROM params.artifact_id
    OR existing.input_digest IS DISTINCT FROM item->>'input_digest'
    OR existing.execution_profile IS DISTINCT FROM item->'execution_profile'
    THEN RETURN false; END IF;
  ELSE
   INSERT INTO photo.tasks(id,tenant_id,run_id,node_key,operation,
    operation_version,resource_class,inputs,params_artifact_id,
    input_digest,execution_profile)
   VALUES(expected_id,p_tenant,p_run,item->>'node_key','session.describe',
    '1','gpu','[]'::jsonb,params.artifact_id,item->>'input_digest',
    item->'execution_profile');
  END IF;
  ordinal:=ordinal+1;
 END LOOP;
 RETURN (SELECT count(*)=expected_count FROM photo.tasks t
  WHERE t.tenant_id=p_tenant AND t.run_id=p_run);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.stage_v22_analysis_describes(uuid,uuid,jsonb) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.stage_v22_analysis_describes(uuid,uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.stage_v22_analysis_describes(uuid,uuid,jsonb) TO photo_scheduler;

-- Source: 00197_analysis_image_source.sql
-- The trusted compiler reads only the frozen run snapshot. Object locations
-- are never exposed to API or worker roles by these functions.
-- +goose StatementBegin
CREATE FUNCTION photo.v22_analysis_image_sources(p_tenant uuid,p_run uuid)
RETURNS TABLE(ordinal integer,asset_version_id uuid,artifact_id uuid,sha256 text,
 bytes bigint,bucket text,object_key text,object_version text,media_type text,
 captured_at text,camera_hash text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT i.ordinal,i.asset_version_id,a.id,a.sha256,a.bytes,a.bucket,
  a.object_key,a.object_version,a.media_type,i.payload->>'captured_at',
  i.payload->>'camera_hash'
 FROM photo.runs r JOIN photo.v2_workflows w
  ON w.tenant_id=r.tenant_id AND w.run_id=r.id
 JOIN photo.snapshots s ON s.tenant_id=r.tenant_id AND s.id=r.input_snapshot_id
 JOIN photo.snapshot_items i ON i.tenant_id=s.tenant_id AND i.snapshot_id=s.id
 JOIN photo.asset_versions v ON v.tenant_id=i.tenant_id AND v.id=i.asset_version_id
  AND v.master_artifact_id=i.artifact_id AND v.content_hash=i.sha256
 JOIN photo.artifacts a ON a.tenant_id=i.tenant_id AND a.id=i.artifact_id
  AND a.sha256=i.sha256
 JOIN photo.tenants t ON t.id=r.tenant_id
 WHERE r.tenant_id=p_tenant AND r.id=p_run AND r.kind='v2'
  AND r.status='draft' AND NOT r.cancel_requested AND NOT r.graph_sealed
  AND w.workflow_type='session' AND w.renderer_version='v2.2'
  AND w.input_snapshot_id=s.id AND s.kind='v2' AND s.expires_at IS NULL
  AND s.principal_type='user' AND s.principal_id=r.created_by
  AND s.digest=r.config_snapshot->'v22_session_plan'->>'snapshot_digest'
  AND s.item_count=(r.config_snapshot->'v22_session_plan'->>'item_count')::integer
  AND t.status='active' AND i.ordinal BETWEEN 0 AND s.item_count-1
  AND a.state='ready' AND a.output_role='working_image'
  AND a.media_type='application/json' AND a.bytes BETWEEN 2 AND 1048576
  AND a.object_version IS NOT NULL AND a.object_version NOT IN ('','null')
  AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp())
 ORDER BY i.ordinal;
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_analysis_image_sources(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_analysis_image_sources(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v22_analysis_image_sources(uuid,uuid) TO photo_scheduler;

-- A selected recipe is the exact immutable document pinned in the pending
-- recovery packet, even if the current draft stream advances before retry.
-- +goose StatementBegin
CREATE FUNCTION photo.v22_analysis_recipe_sources(p_tenant uuid,p_run uuid)
RETURNS TABLE(ordinal integer,asset_version_id uuid,artifact_id uuid,sha256 text,
 bytes bigint,bucket text,object_key text,object_version text,media_type text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT i.ordinal,i.asset_version_id,d.artifact_id,d.sha256,
  a.bytes,a.bucket,a.object_key,a.object_version,a.media_type
 FROM photo.runs r JOIN photo.v2_workflows w
  ON w.tenant_id=r.tenant_id AND w.run_id=r.id
 JOIN photo.idempotency_records idem ON idem.tenant_id=r.tenant_id
  AND idem.resource_id=r.id AND idem.principal_type='user'
  AND idem.principal_id=r.created_by AND idem.route='V2.Admit'
  AND idem.response_status IS NULL
 JOIN photo.snapshots s ON s.tenant_id=r.tenant_id AND s.id=r.input_snapshot_id
 JOIN photo.snapshot_items i ON i.tenant_id=s.tenant_id AND i.snapshot_id=s.id
 JOIN photo.v2_document_streams stream ON stream.tenant_id=r.tenant_id
  AND stream.project_id=w.project_id AND stream.asset_version_id=i.asset_version_id
  AND stream.stream_type='draft'
 JOIN photo.v2_documents d ON d.tenant_id=stream.tenant_id
  AND d.stream_id=stream.id
  AND d.project_id=stream.project_id AND d.document_type='EditingRecipeV3'
  AND d.artifact_id::text=idem.response_body->'snapshot'->'items'->(i.ordinal::integer)->'recipe'->>'artifact_id'
  AND d.sha256=idem.response_body->'snapshot'->'items'->(i.ordinal::integer)->'recipe'->>'sha256'
 JOIN photo.artifacts a ON a.tenant_id=d.tenant_id AND a.id=d.artifact_id
  AND a.sha256=d.sha256
 JOIN photo.tenants t ON t.id=r.tenant_id
 WHERE r.tenant_id=p_tenant AND r.id=p_run AND r.kind='v2'
  AND r.status='draft' AND NOT r.cancel_requested AND NOT r.graph_sealed
  AND w.workflow_type='session' AND w.renderer_version='v2.2'
  AND w.input_snapshot_id=s.id
  AND s.kind='v2' AND s.expires_at IS NULL
  AND s.digest=r.config_snapshot->'v22_session_plan'->>'snapshot_digest'
  AND t.status='active' AND a.state='ready' AND a.output_role='document'
  AND a.media_type='application/json' AND a.object_version IS NOT NULL
  AND a.object_version NOT IN ('','null')
  AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp())
 ORDER BY i.ordinal;
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_analysis_recipe_sources(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_analysis_recipe_sources(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v22_analysis_recipe_sources(uuid,uuid) TO photo_scheduler;

-- Resolve the complete selected inventory before freeze, under the same
-- authorization and revision preflight used by freeze itself. The compiler
-- hashes these refs into InputSnapshot; freeze then copies exactly these
-- snapshot_items and repeats preflight in its own transaction.
-- +goose StatementBegin
CREATE FUNCTION photo.v22_analysis_selection_sources(p_tenant uuid,p_session uuid,
 p_expected bigint,p_selection uuid,p_manual jsonb,p_actor uuid,p_auth_session uuid)
RETURNS TABLE(ordinal integer,asset_version_id uuid,artifact_id uuid,sha256 text,
 bytes bigint,bucket text,object_key text,object_version text,media_type text,
 captured_at text,camera_hash text,recipe_artifact_id uuid,recipe_sha256 text,
 recipe_bytes bigint,recipe_bucket text,recipe_key text,recipe_version text,
 recipe_media_type text,
 selection_item_count bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 WITH authorized AS (
  SELECT photo.preflight_v22_analysis(p_tenant,p_session,p_expected,p_selection,
   p_manual,p_actor,p_auth_session) AS context
 )
 SELECT i.ordinal,i.asset_version_id,a.id,a.sha256,a.bytes,a.bucket,
  a.object_key,a.object_version,a.media_type,i.payload->>'captured_at',
  i.payload->>'camera_hash',d.artifact_id,d.sha256,recipe.bytes,
  recipe.bucket,recipe.object_key,recipe.object_version,recipe.media_type,
  s.item_count
 FROM authorized gate JOIN photo.snapshots s
  ON s.tenant_id=p_tenant AND s.id=p_selection
 JOIN photo.snapshot_items i ON i.tenant_id=s.tenant_id AND i.snapshot_id=s.id
 JOIN photo.asset_versions v ON v.tenant_id=i.tenant_id
  AND v.id=i.asset_version_id AND v.master_artifact_id=i.artifact_id
  AND v.content_hash=i.sha256
 JOIN photo.artifacts a ON a.tenant_id=i.tenant_id AND a.id=i.artifact_id
  AND a.sha256=i.sha256
 JOIN photo.shoot_sessions session ON session.tenant_id=p_tenant
  AND session.id=p_session AND session.collection_id=s.collection_id
 JOIN photo.v2_document_streams stream ON stream.tenant_id=p_tenant
  AND stream.project_id=session.project_id AND stream.asset_version_id=i.asset_version_id
  AND stream.stream_type='draft'
 JOIN photo.v2_documents d ON d.tenant_id=stream.tenant_id
  AND d.id=stream.current_document_id AND d.stream_id=stream.id
  AND d.project_id=stream.project_id AND d.document_type='EditingRecipeV3'
 JOIN photo.artifacts recipe ON recipe.tenant_id=d.tenant_id
  AND recipe.id=d.artifact_id AND recipe.sha256=d.sha256
 WHERE gate.context->>'selection_snapshot_id'=p_selection::text
  AND a.state='ready' AND a.output_role='working_image'
  AND a.media_type='application/json' AND a.bytes BETWEEN 2 AND 1048576
  AND a.object_version IS NOT NULL AND a.object_version NOT IN ('','null')
  AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp())
  AND recipe.state='ready' AND recipe.output_role='document'
  AND recipe.media_type='application/json'
  AND recipe.object_version IS NOT NULL AND recipe.object_version NOT IN ('','null')
  AND (recipe.expires_at IS NULL OR recipe.expires_at>clock_timestamp())
 ORDER BY i.ordinal;
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_analysis_selection_sources(uuid,uuid,bigint,uuid,jsonb,uuid,uuid)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_analysis_selection_sources(uuid,uuid,bigint,uuid,jsonb,uuid,uuid)
 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v22_analysis_selection_sources(uuid,uuid,bigint,uuid,jsonb,uuid,uuid)
 TO photo_scheduler;

-- Child ref must be a ready output of the exact same canonical producer
-- attempt as the WorkingImage declared by the frozen snapshot item.
-- +goose StatementBegin
CREATE FUNCTION photo.v22_analysis_image_child(p_tenant uuid,p_run uuid,
 p_parent uuid,p_parent_sha text,p_child uuid,p_child_sha text,p_role text)
RETURNS TABLE(artifact_id uuid,sha256 text,bytes bigint,bucket text,
 object_key text,object_version text,media_type text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT child.id,child.sha256,child.bytes,child.bucket,child.object_key,
  child.object_version,child.media_type
 FROM photo.runs r JOIN photo.v2_workflows w
  ON w.tenant_id=r.tenant_id AND w.run_id=r.id
 JOIN photo.snapshot_items i ON i.tenant_id=r.tenant_id
  AND i.snapshot_id=r.input_snapshot_id AND i.artifact_id=p_parent
  AND i.sha256=p_parent_sha
 JOIN photo.artifacts parent ON parent.tenant_id=i.tenant_id
  AND parent.id=i.artifact_id AND parent.sha256=i.sha256
 JOIN photo.artifacts child ON child.tenant_id=parent.tenant_id
  AND child.id=p_child AND child.sha256=p_child_sha
 WHERE r.tenant_id=p_tenant AND r.id=p_run AND r.kind='v2'
  AND r.status='draft' AND NOT r.cancel_requested AND NOT r.graph_sealed
  AND w.workflow_type='session' AND w.renderer_version='v2.2'
  AND parent.state='ready' AND parent.output_role='working_image'
  AND parent.created_by_task_id IS NOT NULL
  AND parent.produced_attempt IS NOT NULL AND parent.produced_fence IS NOT NULL
  AND child.created_by_task_id=parent.created_by_task_id
  AND child.produced_attempt=parent.produced_attempt
  AND child.produced_fence=parent.produced_fence
  AND p_role IN ('working_rgb','alpha') AND child.output_role=p_role
  AND child.media_type='application/octet-stream' AND child.bytes>0
  AND child.state='ready' AND child.object_version IS NOT NULL
  AND child.object_version NOT IN ('','null')
  AND (child.expires_at IS NULL OR child.expires_at>clock_timestamp());
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_analysis_image_child(uuid,uuid,uuid,text,uuid,text,text)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_analysis_image_child(uuid,uuid,uuid,text,uuid,text,text)
 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v22_analysis_image_child(uuid,uuid,uuid,text,uuid,text,text)
 TO photo_scheduler;

-- Source: 00197_analysis_consent_source.sql
-- Read only the currently granted identity consents needed by confirmed
-- observations of the frozen analysis inventory. A later admission step must
-- pin these epochs in workflow_consent_links before publishing this body.
-- +goose StatementBegin
CREATE FUNCTION photo.v22_analysis_consent_sources(p_tenant uuid,p_run uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 WITH scope AS (
  SELECT w.project_id,r.input_snapshot_id
  FROM photo.runs r JOIN photo.v2_workflows w
   ON w.tenant_id=r.tenant_id AND w.run_id=r.id
  JOIN photo.snapshots s ON s.tenant_id=r.tenant_id
   AND s.id=r.input_snapshot_id
  JOIN photo.tenants t ON t.id=r.tenant_id
  WHERE r.tenant_id=p_tenant AND r.id=p_run AND r.kind='v2'
   AND r.status='draft' AND NOT r.cancel_requested AND NOT r.graph_sealed
   AND w.workflow_type='session' AND w.renderer_version='v2.2'
   AND w.input_snapshot_id=s.id AND s.kind='v2' AND s.expires_at IS NULL
   AND t.status='active'
 ), matched AS (
  SELECT observation.asset_version_id,observation.face_id,
   observation.person_id,grant_row.id AS consent_id,grant_row.epoch
  FROM scope JOIN photo.snapshot_items item
   ON item.tenant_id=p_tenant AND item.snapshot_id=scope.input_snapshot_id
  JOIN photo.person_observations observation
   ON observation.tenant_id=item.tenant_id
   AND observation.project_id=scope.project_id
   AND observation.asset_version_id=item.asset_version_id
   AND observation.confirmed_by IS NOT NULL
  JOIN photo.project_persons person ON person.tenant_id=observation.tenant_id
   AND person.project_id=observation.project_id
   AND person.id=observation.person_id AND person.state='active'
  JOIN photo.consent_grants grant_row ON grant_row.tenant_id=person.tenant_id
   AND grant_row.project_id=person.project_id
   AND grant_row.person_id=person.id AND grant_row.purpose='identity_matching'
   AND grant_row.status='granted'
 ), grants AS (
  SELECT DISTINCT matched.consent_id,matched.epoch,matched.person_id
  FROM matched
 ), aggregate AS (
  SELECT (SELECT count(*) FROM grants) AS grant_count,
   (SELECT count(*) FROM matched) AS face_count,
   (SELECT coalesce(jsonb_agg(jsonb_build_object(
    'consent_id',consent_id,'epoch',epoch::text,'person_id',person_id,
    'purpose','identity_matching') ORDER BY consent_id), '[]'::jsonb)
    FROM grants) AS grant_body,
   (SELECT coalesce(jsonb_agg(jsonb_build_object(
    'asset_version_id',asset_version_id,'face_id',face_id,'person_id',person_id,
    'consent_id',consent_id,'epoch',epoch::text)
    ORDER BY asset_version_id,face_id), '[]'::jsonb)
    FROM matched) AS face_body
 )
 SELECT CASE WHEN EXISTS(SELECT 1 FROM scope)
  AND aggregate.grant_count<=5000 AND aggregate.face_count<=12800
  THEN jsonb_build_object('schema_version',1,'grants',aggregate.grant_body,
   'confirmed_faces',aggregate.face_body) ELSE NULL::jsonb END
 FROM aggregate;
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v22_analysis_consent_sources(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v22_analysis_consent_sources(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v22_analysis_consent_sources(uuid,uuid) TO photo_scheduler;

-- Source: 00197_analysis_consent_pin.sql
-- Pin the exact consent document and its grant epochs before object upload.
-- This is one transaction: a later revoke locks the same tenant/grant rows
-- and cancels linked workflows before any task can use stale identity data.
-- +goose StatementBegin
CREATE FUNCTION photo.pin_v22_analysis_consents(p_tenant uuid,p_run uuid,
 p_body jsonb,p_sha text,p_bytes bigint,p_bucket text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE workflow uuid; project uuid; grant_item jsonb; grant_row photo.consent_grants%ROWTYPE;
 reservation record;
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL OR p_sha IS NULL OR
  p_sha !~ '^[0-9a-f]{64}$' OR p_bytes NOT BETWEEN 2 AND 8388608 OR
  jsonb_typeof(p_body) IS DISTINCT FROM 'object' OR
  p_bucket IS NULL OR length(p_bucket) NOT BETWEEN 3 AND 63 THEN RETURN false; END IF;
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT w.id,w.project_id INTO workflow,project FROM photo.v2_workflows w
  JOIN photo.runs r ON r.tenant_id=w.tenant_id AND r.id=w.run_id
  WHERE w.tenant_id=p_tenant AND w.run_id=p_run
   AND w.workflow_type='session' AND w.renderer_version='v2.2'
   AND r.kind='v2' AND r.status='draft' AND NOT r.cancel_requested
   AND NOT r.graph_sealed;
 IF workflow IS NULL OR
  p_body IS DISTINCT FROM photo.v22_analysis_consent_sources(p_tenant,p_run)
  THEN RETURN false; END IF;
 FOR grant_item IN SELECT value FROM jsonb_array_elements(p_body->'grants') LOOP
  SELECT * INTO grant_row FROM photo.consent_grants g
   WHERE g.tenant_id=p_tenant AND g.project_id=project
    AND g.id=(grant_item->>'consent_id')::uuid FOR SHARE;
  IF grant_row.id IS NULL OR grant_row.status<>'granted' OR
   grant_row.epoch::text<>grant_item->>'epoch' THEN RETURN false; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM photo.workflow_consent_links link
  WHERE link.tenant_id=p_tenant AND link.workflow_id=workflow
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_body->'grants') item
    WHERE item->>'consent_id'=link.consent_id::text
     AND item->>'epoch'=link.consent_epoch::text)) THEN RETURN false; END IF;
 SELECT * INTO reservation FROM photo.reserve_v22_analysis_document(
  p_tenant,p_run,p_run,'v2_analysis_consents',p_sha,p_bytes,p_bucket);
 IF reservation.outcome NOT IN ('created','resumed','replayed') THEN RETURN false; END IF;
 FOR grant_item IN SELECT value FROM jsonb_array_elements(p_body->'grants') LOOP
  INSERT INTO photo.workflow_consent_links(tenant_id,project_id,workflow_id,
   consent_id,consent_epoch)
  VALUES(p_tenant,project,workflow,(grant_item->>'consent_id')::uuid,
   (grant_item->>'epoch')::bigint)
  ON CONFLICT (tenant_id,workflow_id,consent_id) DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM photo.workflow_consent_links link
   WHERE link.tenant_id=p_tenant AND link.workflow_id=workflow
    AND link.consent_id=(grant_item->>'consent_id')::uuid
    AND link.consent_epoch=(grant_item->>'epoch')::bigint) THEN
   RAISE EXCEPTION 'V22_CONSENT_PIN_CONFLICT' USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.pin_v22_analysis_consents(uuid,uuid,jsonb,text,bigint,text)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.pin_v22_analysis_consents(uuid,uuid,jsonb,text,bigint,text)
 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.pin_v22_analysis_consents(uuid,uuid,jsonb,text,bigint,text)
 TO photo_scheduler;

-- Source: 00197_gc_purge.sql
-- Generated by scripts/build-v22-gc-purge.py; do not edit.
-- V22 references and tenant metadata are covered only after object cleanup.
-- Every V21 artifact-bearing row holds its bytes for its own lifecycle.
-- This helper must be incorporated into both artifact_has_references and the
-- claim_artifact_gc candidate predicate in the final migration.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.v2_artifact_has_references(p_tenant uuid,p_artifact uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT
  EXISTS(SELECT FROM photo.v2_documents x WHERE x.tenant_id=p_tenant AND x.artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_document_refs x WHERE x.tenant_id=p_tenant AND x.artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_artifact_links x WHERE x.tenant_id=p_tenant AND x.artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_task_inputs x WHERE x.tenant_id=p_tenant AND x.artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_document_approvals x WHERE x.tenant_id=p_tenant AND x.resolved_artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_review_batches x WHERE x.tenant_id=p_tenant AND x.decisions_artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.model_qualifications x WHERE x.tenant_id=p_tenant AND x.report_artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.session_analyses x WHERE x.tenant_id=p_tenant AND x.plan_artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.person_observations x WHERE x.tenant_id=p_tenant AND x.evidence_artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_draft_uploads x WHERE x.tenant_id=p_tenant AND x.artifact_id=p_artifact AND x.state='ready')
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_artifact_has_references(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_artifact_has_references(uuid,uuid) FROM PUBLIC;

-- Extend the existing closed tenant purge allowlist after object cleanup proof.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.finish_tenant_deletion(p_job uuid,p_token uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE j photo.deletion_jobs%ROWTYPE;t text;
 tables_to_purge constant text[]:=ARRAY[
  'workflow_consent_links','consent_events','person_observations','scene_members','scene_groups','session_analyses','consent_grants','project_persons','shoot_sessions',
  'v2_document_approvals','v2_document_refs','v2_task_inputs','v2_review_batches','v2_artifact_links','model_qualifications','v2_documents','v2_document_streams','v2_workflows','v2_draft_uploads',
  'apply_v4_stages','apply_nodes','apply_builds','artifact_leases','asset_embeddings','asset_version_sources','bulk_item_results','collection_items',
  'dead_letters','defect_branches','derivatives','download_archive_plans','download_export_plans','download_intents','download_job_items','download_volumes','editor_drafts','export_batch_children','graph_expansions','ingest_catalog_items','ingest_decode_items','ingest_node_plans','ingest_originals','ingest_progress','ingest_rejections','interactive_tasks','media_retry_nodes','output_uploads','project_acl','publications','resource_reservations','resource_slots','result_cache','reviews','run_events','sections','share_sessions','snapshot_items','staging_cleanup','style_analysis_nodes','style_asset_bindings','style_candidates','style_import_builds','task_attempts','task_edges','task_results','training_pairs','upload_abort_cleanup','upload_parts','asset_versions','assets','backend_documents','bulk_operations','collections','download_build_state','download_jobs','export_batches','exports','ingest_upload_bindings','legacy_imports','media_retry_jobs','overrides','quota_reservations','share_links','snapshots','style_analysis_builds','style_versions','tasks','training_sets','upload_sessions','tenant_static_resources','artifacts','runs','styles','projects','export_presets','idempotency_records','inbox','invitations','outbox','scheduler_tenants','tenant_event_cursors','tenant_usage','worker_registrations'
 ];
BEGIN
 SELECT * INTO j FROM photo.deletion_jobs WHERE id=p_job AND resource_type='tenant' AND status='running' AND cleanup_token=p_token AND cleanup_lease_until>clock_timestamp() FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT FROM photo.tenants x WHERE x.id=j.tenant_id AND x.status='deleting') OR EXISTS(SELECT FROM photo.runs r WHERE r.tenant_id=j.tenant_id AND r.status IN('draft','queued','running','waiting_review','cancelling')) THEN RETURN false;END IF;
 SET CONSTRAINTS ALL DEFERRED;
 UPDATE photo.v2_document_streams SET current_document_id=NULL,approved_document_id=NULL WHERE tenant_id=j.tenant_id;
 FOREACH t IN ARRAY tables_to_purge LOOP EXECUTE format('DELETE FROM photo.%I WHERE tenant_id=$1',t) USING j.tenant_id;END LOOP;
 DELETE FROM photo.audit_log WHERE tenant_id=j.tenant_id AND action NOT LIKE 'tenant.%';UPDATE photo.memberships SET status='suspended',revision=revision+1 WHERE tenant_id=j.tenant_id AND status<>'suspended';
 INSERT INTO photo.audit_log(tenant_id,actor_type,actor_id,action,resource_type,resource_id,request_id,details) VALUES(j.tenant_id,'system',NULL,'tenant.deleted','tenant',j.tenant_id,gen_random_uuid(),jsonb_build_object('job_id',j.id,'cleanup_passes',j.cleanup_passes+1));
 UPDATE photo.tenants SET status='deleted',revision=revision+1 WHERE id=j.tenant_id AND status='deleting';UPDATE photo.deletion_jobs SET status='completed',cleanup_token=NULL,cleanup_lease_until=NULL,cleanup_passes=cleanup_passes+1,cursor=NULL,error=NULL WHERE id=j.id;SET CONSTRAINTS ALL IMMEDIATE;RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.finish_tenant_deletion(uuid,uuid) OWNER TO photo_fn_owner;

